-- LifeLine 0.9.0 - versione applicativa + 54 modelli di chiamata (39 nuovi)
UPDATE lifeline_settings SET value = '0.9.0' WHERE key_name = 'app_version';

SET NAMES utf8mb4;

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('IMP_003', 'Farmacia di turno', 'impropria', 1, 1, 90, 1, 'sera,notte', 0, 0, '{"code":"IMP_003","title":"Farmacia di turno","category":"impropria","phase":1,"difficulty":1,"weight":90,"min_rank":1,"time_bands":["sera","notte"],"lang":"it","variables":{"location":{"pool":"stradario","zones":["centro","residenziale","colline"],"floor":[0,3]},"req":{"choice":[{"text":"No no, nessuna emergenza, per carità. Mi serve solo un collirio.","display":"Nessuna emergenza: cerca un collirio","detail_text":"Nessun dolore, è solo per gli occhi un po'' irritati.","detail_display":"Nessun sintomo rilevante","event":"impropria.informazioni","agencies":[]},{"text":"Beh… mia figlia ha la febbre a 39 da stasera, volevo prendere uno sciroppo.","display":"La figlia ha febbre a 39, cerca un antipiretico","detail_text":"È un po'' abbattuta ma gioca, beve, risponde normalmente.","detail_display":"Bambina vigile, beve e risponde","event":"impropria.informazioni","agencies":[]},{"text":"Ecco… è per mio marito. Ha un dolore al petto da un''ora, pensavo a un antiacido…","display":"Il marito ha dolore al petto da un''ora","detail_text":"Gli prende tutto il petto e va verso il braccio sinistro… ed è tutto sudato.","detail_display":"Dolore al petto irradiato al braccio sinistro, sudorazione","event":"sanitaria.dolore_toracico","agencies":["118"]}],"weights":[55,30,15]}},"caller":{"gender":"f","phone_type":"any","panic_start":5,"ring_patience_s":60,"hold_patience_s":90,"reliability":1,"callback_chance":0.3},"opening":{"calm":"Salve, scusi il disturbo… volevo sapere qual è la farmacia di turno stanotte.","panic":"Salve, scusi… mi serve una farmacia aperta, qual è quella di turno?"},"facts":{"richiesta":{"display":"{req.display}"},"stato":{"display":"{req.detail_display}"},"indirizzo":{"display":"{location.street} {location.number}, {location.zone_name}"}},"nodes":[{"id":"q_emergenza","label":"Per chi le serve? C''è qualcuno che sta male adesso?","cost_s":6,"reveals":["richiesta"],"reply":{"calm":"{req.text}","panic":"{req.text}"}},{"id":"q_dettagli","label":"Mi descriva i sintomi: da quanto tempo e come sta adesso?","cost_s":8,"requires":["q_emergenza"],"reveals":["stato"],"reply":{"calm":"{req.detail_text}","panic":"{req.detail_text}"}},{"id":"q_dove","label":"Da dove chiama? Mi dica l''indirizzo.","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":"Da casa, in {location.street} {location.number}.","panic":"{location.street} {location.number}."}}],"truth":{"event_type":"{req.event}","agencies_required":["{req.agencies}"],"severity":{"optimal_s":240,"acceptable_s":600,"limit_s":1500},"critical_facts":["richiesta"],"hint_debrief":"Le chiamate per informazioni vanno chiuse in fretta, ma solo dopo aver escluso un''emergenza: a volte chi chiede una farmacia sta descrivendo un infarto."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('IMP_004', 'Scherzo telefonico', 'impropria', 1, 2, 80, 1, 'pomeriggio,sera', 0, 0, '{"code":"IMP_004","title":"Scherzo telefonico","category":"impropria","phase":1,"difficulty":2,"weight":80,"min_rank":1,"time_bands":["pomeriggio","sera"],"lang":"it","variables":{"location":{"pool":"stradario","zones":["residenziale","centro"],"floor":[0,0]},"prank":{"choice":[{"opening":"(risatine in sottofondo) Pronto… c''è un incendio… sulla Luna!","where":"Sulla Luna, gliel''ho detto! (risate)","where_display":"Dice «sulla Luna», tra le risate"},{"opening":"C''è… c''è un incendio in {location.street}! (una risata soffocata)","where":"Ehm… in {location.street}… al… al numero mille! (risate)","where_display":"{location.street} «numero mille», tra le risate"},{"opening":"Pronto, polizia? Il mio amico è stato rapito dagli alieni!","where":"Nel campo dietro la scuola… anzi no, su Marte!","where_display":"Indicazioni contraddittorie, tra le risate"}]}},"caller":{"gender":"m","phone_type":"mobile","panic_start":5,"ring_patience_s":20,"hold_patience_s":10,"reliability":0.3,"callback_chance":0.15},"opening":{"calm":"{prank.opening}","panic":"{prank.opening}"},"facts":{"indirizzo":{"display":"{prank.where_display}"},"evento":{"display":"Racconto confuso, cambia versione"},"ambiente":{"label":"Rumori di fondo","display":"Risate di altri ragazzi, nessun rumore di emergenza"}},"nodes":[{"id":"q_dove","label":"Dove si trova esattamente?","cost_s":5,"reveals":["indirizzo"],"reply":{"calm":"{prank.where}","panic":"{prank.where}"}},{"id":"q_ripeti","label":"Mi ripeta con calma cosa sta succedendo.","cost_s":6,"reveals":["evento"],"reply":{"calm":"Eh… c''è… c''è un problema grosso! (si sente qualcuno che gli suggerisce qualcosa)","panic":"C''è un problema grosso!"}},{"id":"q_ambiente","label":"Sento delle voci. Chi c''è lì con te?","cost_s":5,"reveals":["ambiente"],"reply":{"calm":"Nessuno! (in sottofondo: «dai, digli che…» e altre risate)","panic":"Nessuno, nessuno!"}},{"id":"q_adulto","label":"Quanti anni hai? Passami un adulto, per favore.","cost_s":5,"ends_call":true,"reply":{"calm":"(risate, poi riattaccano)","panic":"(riattaccano)"}}],"truth":{"event_type":"impropria.scherzo","agencies_required":[],"severity":{"optimal_s":60,"acceptable_s":120,"limit_s":600},"critical_facts":["indirizzo"],"hint_debrief":"Uno scherzo si riconosce da incoerenze e rumori di fondo; va chiuso rapidamente per liberare la linea, ma solo dopo un paio di verifiche."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('IMP_046', 'Chiamata muta', 'impropria', 1, 4, 100, 1, 'mattina,pomeriggio,sera,notte', 0, 0, '{"code":"IMP_046","title":"Chiamata muta","category":"impropria","phase":1,"difficulty":4,"weight":100,"min_rank":1,"time_bands":["mattina","pomeriggio","sera","notte"],"lang":"it","variables":{"location":{"pool":"stradario","zones":["centro","residenziale","colline"],"floor":[0,3]},"sc":{"choice":[{"r":"(fruscio continuo, passi, una voce lontana che parla d''altro e ride)","rd":"Fruscio e voci lontane, nessuno risponde","k":"(nessuna reazione, il fruscio continua)","kd":"Nessun tasto premuto","l":"(sembra una tasca: passi, un''auto che passa, una radio)","ld":"Rumori di strada, come un telefono in tasca","dv":"(solo il fruscio, nessuno risponde)","dvd":"Nessuna risposta","event":"impropria.errore","ag":[],"acc":["impropria.chiamata_muta"]},{"r":"(un respiro affannoso… una voce impastata) «…aiu… non…»","rd":"Respiro affannoso, parole impastate","k":"(si sente un tasto premuto, poi un altro)","kd":"Ha premuto i tasti su richiesta","l":"(una televisione accesa, un gemito ogni tanto)","ld":"TV accesa, gemiti","dv":"(una voce faticosa) «…{location.street}… {location.number}…»","dvd":"{location.street} {location.number} (detto a fatica)","event":"sanitaria.ictus","ag":["118"],"acc":["sanitaria.malore","sanitaria.incosciente"]},{"r":"(una vocina) «Ciao! Chi sei? Io sono Sofia!»","rd":"Voce di bambina che gioca","k":"(bip bip bip, risatine)","kd":"Tasti premuti a caso, risate","l":"(una mamma in lontananza: «Sofia, dov''è il mio telefono?»)","ld":"Voce di un adulto che cerca il telefono","dv":"(la bambina) «Io abito nella casa gialla!»","dvd":"«La casa gialla» (bambina)","event":"impropria.errore","ag":[],"acc":["impropria.scherzo"]}],"weights":[45,25,30]}},"caller":{"gender":"any","phone_type":"any","panic_start":20,"ring_patience_s":40,"hold_patience_s":30,"reliability":1,"callback_chance":0.2},"opening":{"calm":"(silenzio… un fruscio)","panic":"(silenzio… un fruscio)"},"facts":{"indirizzo":{"display":"{sc.dvd}"},"voce":{"label":"Cosa si sente","display":"{sc.rd}"},"segnale":{"label":"Risposta ai tasti","display":"{sc.kd}"},"ambiente":{"label":"Rumori di fondo","display":"{sc.ld}"}},"nodes":[{"id":"q_parla","label":"Pronto, 112. Mi sente? Mi dica dove si trova.","cost_s":6,"reveals":["voce"],"reply":{"calm":"{sc.r}","panic":"{sc.r}"}},{"id":"q_tasto","label":"Se ha bisogno di aiuto e non può parlare, prema un tasto del telefono.","cost_s":8,"reveals":["segnale"],"reply":{"calm":"{sc.k}","panic":"{sc.k}"}},{"id":"q_ascolta","label":"Resto in ascolto qualche secondo in silenzio.","cost_s":10,"reveals":["ambiente"],"reply":{"calm":"{sc.l}","panic":"{sc.l}"}},{"id":"q_dove","label":"Se mi sente, provi a dirmi l''indirizzo.","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":"{sc.dv}","panic":"{sc.dv}"},"requires":["q_tasto"]}],"truth":{"event_type":"{sc.event}","acceptable_event_types":"{sc.acc}","agencies_required":"{sc.ag}","severity":{"optimal_s":300,"acceptable_s":600,"limit_s":1500},"critical_facts":["segnale","ambiente"],"hint_debrief":"Una chiamata muta non si chiude subito: si ascolta, si chiede di premere un tasto. Quasi sempre è un telefono in tasca, ma a volte è qualcuno che non riesce più a parlare."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('IMP_047', 'Richiesta che non è un''emergenza', 'impropria', 1, 1, 100, 1, 'mattina,pomeriggio,sera,notte', 0, 0, '{"code":"IMP_047","title":"Richiesta che non è un''emergenza","category":"impropria","phase":1,"difficulty":1,"weight":100,"min_rank":1,"time_bands":["mattina","pomeriggio","sera","notte"],"lang":"it","variables":{"location":{"pool":"stradario","zones":["centro","residenziale","industriale"],"floor":[0,0]},"sc":{"choice":[{"r":"Un''auto è parcheggiata davanti al mio passo carrabile da due ore e devo uscire per andare al lavoro.","rd":"Auto davanti al passo carrabile"},{"r":"Ieri mi hanno rubato la bicicletta in stazione, volevo fare la denuncia.","rd":"Furto di una bicicletta avvenuto ieri, vuole denunciare"},{"r":"Ho mal di gola da tre giorni, volevo sapere a che ora apre la guardia medica.","rd":"Mal di gola da tre giorni, chiede gli orari della guardia medica"},{"r":"Sono in coda da mezz''ora sulla provinciale, volevo sapere se c''è un incidente.","rd":"Chiede informazioni sul traffico"}]}},"caller":{"gender":"any","phone_type":"any","panic_start":5,"ring_patience_s":60,"hold_patience_s":80,"reliability":1,"callback_chance":0.2},"opening":{"calm":"Buongiorno, chiamo perché ho un problema, forse non è il numero giusto…","panic":"Buongiorno, ho un problema e non so chi chiamare."},"facts":{"richiesta":{"display":"{sc.rd}"},"urgenza":{"label":"Pericolo","display":"Nessuna persona in pericolo"}},"nodes":[{"id":"q_cosa","label":"Mi dica pure: cosa succede?","cost_s":6,"reveals":["richiesta"],"reply":{"calm":"{sc.r}","panic":"{sc.r}"}},{"id":"q_urgenza","label":"C''è qualcuno in pericolo o che si è fatto male?","cost_s":5,"reveals":["urgenza"],"reply":{"calm":"No, no, nessuno sta male.","panic":"No, no, nessuno sta male."}}],"truth":{"event_type":"impropria.informazioni","agencies_required":[],"severity":{"optimal_s":60,"acceptable_s":120,"limit_s":600},"critical_facts":["urgenza"],"hint_debrief":"Richieste come un passo carrabile bloccato o una denuncia vanno indirizzate al servizio giusto (polizia locale, caserma, guardia medica) e chiuse in fretta: la linea serve alle emergenze."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('IMP_048', 'Un anziano che vuole parlare', 'impropria', 1, 3, 100, 1, 'mattina,pomeriggio,sera,notte', 0, 0, '{"code":"IMP_048","title":"Un anziano che vuole parlare","category":"impropria","phase":1,"difficulty":3,"weight":100,"min_rank":1,"time_bands":["mattina","pomeriggio","sera","notte"],"lang":"it","variables":{"location":{"pool":"stradario","zones":["centro","residenziale","colline"],"floor":[0,4]},"sc":{"choice":[{"r":"Sto bene, sto bene… è che da quando è morta mia moglie la sera è lunga, e nessuno mi chiama.","rd":"Solitudine: nessun problema di salute riferito","d":"No, niente, ho mangiato, ho preso le mie pastiglie.","dd":"Nessun sintomo","event":"impropria.informazioni","ag":[],"acc":[]},{"r":"Beh… ieri sono caduto in bagno e da allora sto sulla poltrona, non riesco più ad alzarmi. Ma non volevo disturbare.","rd":"Caduto ieri, da allora non riesce ad alzarsi dalla poltrona","d":"Mi fa male l''anca, e non ho mangiato da ieri.","dd":"Dolore all''anca, digiuno da ieri","event":"sanitaria.trauma_caduta","ag":["118","115"],"acc":["sanitaria.malore"]},{"r":"Mah… stasera mi sento strano, il braccio sinistro mi formicola e la bocca è un po'' addormentata.","rd":"Formicolio al braccio sinistro e alla bocca da stasera","d":"E faccio fatica a trovare le parole… mi scusi.","dd":"Fatica a trovare le parole","event":"sanitaria.ictus","ag":["118"],"acc":["sanitaria.malore"]}],"weights":[45,30,25]}},"caller":{"gender":"m","phone_type":"landline","panic_start":5,"ring_patience_s":60,"hold_patience_s":60,"reliability":1,"callback_chance":0.7},"opening":{"calm":"Buonasera signorina… mi scusi l''ora, volevo solo sentire una voce.","panic":"Buonasera… mi scusi se disturbo."},"facts":{"indirizzo":{"display":"{location.street} {location.number}, {location.zone_name}"},"richiesta":{"display":"{sc.rd}"},"stato":{"display":"{sc.dd}"},"accesso":{"display":"Vive solo; la porta è chiusa a chiave"}},"nodes":[{"id":"q_come","label":"Come sta, signor {caller_surname}? Ha bisogno di qualcosa?","cost_s":8,"reveals":["richiesta"],"reply":{"calm":"{sc.r}","panic":"{sc.r}"}},{"id":"q_salute","label":"Si sente bene? Ha dolori, ha mangiato, ha preso le medicine?","cost_s":7,"reveals":["stato"],"reply":{"calm":"{sc.d}","panic":"{sc.d}"},"requires":["q_come"]},{"id":"q_dove","label":"Mi dice dove abita, signor {caller_surname}?","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":"In {location.street} {location.number}.","panic":"{location.street} {location.number}."}},{"id":"q_solo","label":"Vive da solo? Qualcuno può aprire la porta?","cost_s":5,"reveals":["accesso"],"reply":{"calm":"Sì, da solo. La porta è chiusa a chiave, le chiavi le ho io.","panic":"Sì, da solo. La porta è chiusa a chiave, le chiavi le ho io."}},{"id":"a_rassicura","type":"reassure","label":"Ha fatto bene a chiamare. Non si preoccupi di disturbare.","cost_s":6,"panic_delta":-5,"reply":{"calm":"Grazie… lei è gentile.","panic":"Grazie…"}}],"truth":{"event_type":"{sc.event}","acceptable_event_types":"{sc.acc}","agencies_required":"{sc.ag}","severity":{"optimal_s":420,"acceptable_s":900,"limit_s":1800},"critical_facts":["richiesta","stato"],"hint_debrief":"Chi chiama «solo per sentire una voce» va ascoltato fino in fondo: a volte è solitudine, a volte dietro c''è una caduta o un ictus che la persona minimizza."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('INC_002', 'Cassonetto in fiamme', 'incendio_tecnico', 1, 1, 110, 1, 'pomeriggio,sera,notte', 1, 0, '{"code":"INC_002","title":"Cassonetto in fiamme","category":"incendio_tecnico","phase":1,"difficulty":1,"weight":110,"min_rank":1,"time_bands":["pomeriggio","sera","notte"],"can_duplicate":true,"lang":"it","variables":{"location":{"pool":"stradario","zones":["centro","residenziale","industriale"],"floor":[0,0]},"fire":{"choice":[{"text":"Un cassonetto della plastica, le fiamme saranno alte un metro.","display":"Un cassonetto, fiamme di circa un metro","danger_text":"No, è in mezzo al parcheggio, lontano da tutto.","danger_display":"Lontano da case e auto"},{"text":"Due cassonetti, e il fuoco sta arrivando a una macchina parcheggiata!","display":"Due cassonetti, fiamme vicine a un''auto","danger_text":"Sì! C''è una macchina attaccata, e sopra ci sono le finestre delle case!","danger_display":"Auto parcheggiata e finestre di abitazioni vicine"}],"weights":[65,35]},"people":{"choice":[{"text":"No, qui non c''è nessuno, solo io che guardo.","display":"Nessun ferito","agencies":[]},{"text":"Un signore ha provato a spegnerlo con un secchio e si è bruciato la mano.","display":"Un uomo si è ustionato la mano","agencies":["118"]}],"weights":[80,20]}},"caller":{"gender":"m","phone_type":"mobile","panic_start":15,"ring_patience_s":25,"hold_patience_s":35,"reliability":1,"callback_chance":0.2},"opening":{"calm":"Buonasera, sto passando in {location.street}: c''è un cassonetto che brucia.","panic":"Pronto! C''è un incendio qui in {location.street}, un cassonetto!"},"facts":{"indirizzo":{"display":"{location.street} altezza civico {location.number}, vicino a {location.landmark} ({location.zone_name})"},"incendio":{"display":"{fire.display}"},"pericoli":{"display":"{fire.danger_display}"},"persone":{"display":"{people.display}"}},"nodes":[{"id":"q_dove","label":"Dove si trova esattamente? Mi dia un civico o un punto di riferimento.","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":"In {location.street}, all''altezza del {location.number}, vicino a {location.landmark}.","panic":"In {location.street}, vicino a {location.landmark}!"}},{"id":"q_cosa","label":"Cosa sta bruciando? Quanto sono alte le fiamme?","cost_s":6,"reveals":["incendio"],"reply":{"calm":"{fire.text}","panic":"{fire.text}"}},{"id":"q_vicino","label":"Il fuoco è vicino a case, auto o alberi?","cost_s":5,"requires":["q_cosa"],"reveals":["pericoli"],"reply":{"calm":"{fire.danger_text}","panic":"{fire.danger_text}"}},{"id":"q_persone","label":"Ci sono persone ferite o in pericolo?","cost_s":5,"reveals":["persone"],"reply":{"calm":"{people.text}","panic":"{people.text}"}},{"id":"a_sicurezza","type":"reassure","label":"Si tenga a distanza e non provi a spegnerlo: i soccorsi stanno arrivando.","cost_s":5,"panic_delta":-10,"reply":{"calm":"D''accordo, resto qui sul marciapiede.","panic":"Va bene, va bene, mi allontano."}}],"truth":{"event_type":"incendio_tecnico.incendio_rifiuti","agencies_required":["115","{people.agencies}"],"severity":{"optimal_s":240,"acceptable_s":600,"limit_s":1500},"critical_facts":["indirizzo","persone"],"hint_debrief":"Chiedere sempre se ci sono feriti: anche un incendio banale può richiedere il 118."},"duplicates":{"chance":0.5,"max":2,"delay_s":[20,150],"near_twin_chance":0.2},"witness_opening":{"calm":"Buonasera, c''è un cassonetto in fiamme in {location.street}, vicino a {location.landmark}.","panic":"Pronto, un incendio! Un cassonetto in {location.street}!"}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('INC_009', 'Fumo da un appartamento', 'incendio_tecnico', 1, 4, 85, 1, 'mattina,pomeriggio,sera,notte', 1, 0, '{"code":"INC_009","title":"Fumo da un appartamento","category":"incendio_tecnico","phase":1,"difficulty":4,"weight":85,"min_rank":1,"time_bands":["mattina","pomeriggio","sera","notte"],"can_duplicate":true,"lang":"it","duplicates":{"chance":0.6,"max":2,"delay_s":[30,150],"near_twin_chance":0},"variables":{"location":{"pool":"stradario","zones":["centro","residenziale"],"floor":[1,5]},"people":{"choice":[{"text":"Ci abita la signora Nadia, è anziana e vive da sola… ho suonato ma non risponde!","display":"Anziana sola in casa, non risponde al campanello","agencies":["115","118"]},{"text":"Credo sia al lavoro… ma sento il suo cane che abbaia come un matto.","display":"Probabilmente nessuno in casa, dentro c''è un cane","agencies":["115"]}],"weights":[60,40]}},"caller":{"gender":"f","phone_type":"any","panic_start":55,"ring_patience_s":30,"hold_patience_s":25,"reliability":0.95,"callback_chance":0.8},"opening":{"calm":"Pronto, esce del fumo da sotto la porta della mia vicina, sul pianerottolo.","panic":"Pronto! C''è fumo, esce fumo dall''appartamento della vicina!"},"witness_opening":{"calm":"Buonasera, in {location.street} esce del fumo da una finestra, al {location.floor_text}.","panic":"C''è fumo che esce da una finestra in {location.street}, al {location.floor_text}!"},"facts":{"indirizzo":{"display":"{location.street} {location.number}, {location.zone_name}"},"piano":{"display":"{location.floor_text}"},"persone":{"display":"{people.display}"},"incendio":{"display":"Fumo grigio sempre più denso, odore di bruciato, fiamme non visibili"},"pericoli":{"display":"Nessun odore di gas"}},"nodes":[{"id":"q_dove","label":"Mi dica l''indirizzo, via e civico.","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":"{location.street} {location.number}.","panic":"{location.street}, il {location.number}!"},"error":{"threshold":70,"chance":0.35,"fact":"indirizzo","display":"{location.street} {location.number_wrong}, {location.zone_name}","reply":{"panic":"{location.street}, il {location.number_wrong}! Presto!"}}},{"id":"q_piano","label":"A che piano è l''appartamento?","cost_s":4,"reveals":["piano"],"reply":{"calm":"Al {location.floor_text}.","panic":"{location.floor_text}!"}},{"id":"q_persone","label":"Sa se c''è qualcuno dentro?","cost_s":6,"reveals":["persone"],"reply":{"calm":"{people.text}","panic":"{people.text}"}},{"id":"q_fiamme","label":"Vede fiamme o solo fumo? Com''è il fumo?","cost_s":5,"reveals":["incendio"],"reply":{"calm":"Solo fumo grigio, ma sempre di più. Si sente puzza di bruciato.","panic":"Fumo, tanto fumo, puzza di bruciato!"}},{"id":"q_gas","label":"Sente odore di gas?","cost_s":4,"reveals":["pericoli"],"reply":{"calm":"No, gas no. Solo bruciato.","panic":"No… no, gas no."}},{"id":"a_esci","type":"reassure","label":"Non apra quella porta: esca dal palazzo con gli altri inquilini e aspetti i soccorsi fuori.","cost_s":6,"panic_delta":-18,"reply":{"calm":"D''accordo, avviso gli altri e scendo.","panic":"Sì… sì, scendo subito."}}],"truth":{"event_type":"incendio_tecnico.incendio_abitazione","agencies_required":["{people.agencies}"],"severity":{"optimal_s":240,"acceptable_s":480,"limit_s":1200},"critical_facts":["indirizzo","persone"],"hint_debrief":"In un incendio in casa la domanda chiave è chi c''è dentro: una persona che non risponde richiede anche il 118. Più vicini chiamano per lo stesso fumo: vanno accorpati."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('INC_026', 'Persona caduta nel torrente', 'incendio_tecnico', 1, 6, 100, 1, 'mattina,pomeriggio,sera,notte', 0, 0, '{"code":"INC_026","title":"Persona caduta nel torrente","category":"incendio_tecnico","phase":1,"difficulty":6,"weight":100,"min_rank":1,"time_bands":["mattina","pomeriggio","sera","notte"],"lang":"it","variables":{"location":{"pool":"stradario","zones":["colline","residenziale"],"floor":[0,0],"streets":["Strada Panoramica","Via San Floriano","Via dei Tigli","Via delle Acacie","Via Collalto"]},"sc":{"choice":[{"p":"Un bambino! Stava giocando sulla riva ed è scivolato, la corrente lo porta via!","pd":"Bambino trascinato dalla corrente","w":"Sì, lo vedo, si tiene a un ramo ogni tanto!","wd":"Visibile, si aggrappa a tratti"},{"p":"Un signore che pescava è scivolato, è in acqua fino al petto, aggrappato a un ramo.","pd":"Pescatore in acqua, aggrappato a un ramo","w":"Sì, è fermo lì, ma dice che non ha più forza nelle braccia.","wd":"Fermo, aggrappato, sta perdendo le forze"},{"p":"Il cane è caduto in acqua e il padrone si è buttato a prenderlo! Adesso non riescono a uscire!","pd":"Uomo entrato in acqua per il cane, non riesce a uscire","w":"Sono tutti e due contro un sasso in mezzo, l''acqua è fortissima.","wd":"Bloccati contro un masso a metà torrente"}]}},"caller":{"gender":"m","phone_type":"mobile","panic_start":78,"ring_patience_s":25,"hold_patience_s":12,"reliability":0.95,"callback_chance":0.6},"opening":{"calm":"Pronto! C''è una persona nel torrente, la corrente la porta via!","panic":"Pronto! Qualcuno è caduto nel torrente! Presto!"},"facts":{"indirizzo":{"display":"Torrente, altezza {location.street} (vicino a {location.landmark})"},"persone":{"display":"{sc.pd}"},"stato":{"label":"Dove si trova ora","display":"{sc.wd}"}},"nodes":[{"id":"q_dove","label":"Dove siete? Da che strada si arriva al punto del torrente?","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":"Dalla {location.street}, vicino a {location.landmark}, sotto il ponte.","panic":"{location.street}! Vicino a {location.landmark}!"},"error":{"threshold":65,"chance":0.4,"fact":"indirizzo","display":"{location.street_wrong} (incerto)","reply":{"panic":"In {location.street_wrong}… credo, non ne sono sicuro!"}}},{"id":"q_chi","label":"Chi è in acqua?","cost_s":5,"reveals":["persone"],"reply":{"calm":"{sc.p}","panic":"{sc.p}"}},{"id":"q_vede","label":"Lo vede ancora? Dove si trova adesso?","cost_s":5,"reveals":["stato"],"reply":{"calm":"{sc.w}","panic":"{sc.w}"}},{"id":"a_rassicura","type":"reassure","label":"Non entri in acqua: gli lanci qualcosa a cui aggrapparsi e lo segua dalla riva senza perderlo di vista.","cost_s":6,"panic_delta":-12,"reply":{"calm":"Ok, cerco una corda.","panic":"Sì, sì, non entro!"}}],"truth":{"event_type":"incendio_tecnico.soccorso_persona","acceptable_event_types":["sanitaria.soccorso_impervio"],"agencies_required":["115","118"],"severity":{"optimal_s":180,"acceptable_s":360,"limit_s":900},"critical_facts":["indirizzo","persone"],"hint_debrief":"Il soccorso in acqua richiede Vigili del fuoco e 118 insieme. Mai incoraggiare chi chiama a entrare in acqua: si rischiano due vittime."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('INC_027', 'Mia madre non risponde al telefono', 'incendio_tecnico', 1, 4, 100, 1, 'mattina,pomeriggio,sera,notte', 0, 0, '{"code":"INC_027","title":"Mia madre non risponde al telefono","category":"incendio_tecnico","phase":1,"difficulty":4,"weight":100,"min_rank":1,"time_bands":["mattina","pomeriggio","sera","notte"],"lang":"it","aml":{"available":false},"variables":{"location":{"pool":"stradario","zones":["centro","residenziale","colline"],"floor":[0,4]},"sc":{"choice":[{"s":"Le persiane sono chiuse da ieri, la vicina dice che c''è ancora la posta nella cassetta.","sd":"Persiane chiuse da ieri, posta non ritirata"},{"s":"La vicina mi ha detto che stamattina ha sentito dei lamenti attraverso il muro.","sd":"La vicina ha sentito lamenti dall''interno"}]}},"caller":{"gender":"f","phone_type":"mobile","panic_start":45,"ring_patience_s":35,"hold_patience_s":30,"reliability":0.95,"callback_chance":0.8},"opening":{"calm":"Buonasera, chiamo da Milano: mia madre abita a Valdemara e non risponde al telefono da ieri sera. Ha 84 anni e vive da sola.","panic":"Pronto, mia madre non risponde da ieri, è anziana e vive sola, sono preoccupatissima!"},"facts":{"indirizzo":{"display":"Casa della madre: {location.street} {location.number}, {location.floor_text}"},"segni":{"label":"Segnali","display":"{sc.sd}"},"chiavi":{"label":"Chiavi","display":"Nessuno ha le chiavi a Valdemara"},"salute":{"label":"Salute","display":"Cardiopatica, cammina con il bastone"}},"nodes":[{"id":"q_dove","label":"Qual è l''indirizzo di sua madre, con il piano?","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":"{location.street} {location.number}, al {location.floor_text}.","panic":"{location.street} {location.number}!"},"error":{"threshold":65,"chance":0.4,"fact":"indirizzo","display":"{location.street} {location.number_wrong}, {location.zone_name}","reply":{"panic":"{location.street}… il {location.number_wrong}!"}}},{"id":"q_segni","label":"Qualcuno ha notato qualcosa? Vicini, portinaio?","cost_s":6,"reveals":["segni"],"reply":{"calm":"{sc.s}","panic":"{sc.s}"}},{"id":"q_chiavi","label":"Qualcuno lì vicino ha le chiavi di casa?","cost_s":5,"reveals":["chiavi"],"reply":{"calm":"No… le ho solo io, e sono a trecento chilometri.","panic":"No… le ho solo io, e sono a trecento chilometri."}},{"id":"q_salute","label":"Sua madre ha problemi di salute?","cost_s":5,"reveals":["salute"],"reply":{"calm":"È cardiopatica e cammina con il bastone.","panic":"È cardiopatica e cammina con il bastone."}},{"id":"a_rassicura","type":"reassure","label":"Facciamo verificare subito. Tenga il telefono libero: la richiameranno i soccorritori.","cost_s":6,"panic_delta":-15,"reply":{"calm":"Va bene… grazie.","panic":"Sì… sì, va bene."}}],"truth":{"event_type":"incendio_tecnico.apertura_porta","acceptable_event_types":["sanitaria.malore","sanitaria.incosciente","incendio_tecnico.soccorso_persona"],"agencies_required":["115","118"],"severity":{"optimal_s":600,"acceptable_s":1200,"limit_s":2400},"critical_facts":["indirizzo","chiavi"],"hint_debrief":"Chi chiama da lontano non è sul posto: il cerchio AML non serve, conta l''indirizzo della persona. Senza chiavi servono i Vigili del fuoco per entrare, con il 118."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('INC_028', 'Auto in fiamme', 'incendio_tecnico', 1, 3, 100, 1, 'mattina,pomeriggio,sera,notte', 1, 0, '{"code":"INC_028","title":"Auto in fiamme","category":"incendio_tecnico","phase":1,"difficulty":3,"weight":100,"min_rank":1,"time_bands":["mattina","pomeriggio","sera","notte"],"lang":"it","can_duplicate":true,"duplicates":{"chance":0.45,"max":2,"delay_s":[20,140],"near_twin_chance":0.15},"witness_opening":{"calm":"Buonasera, in {location.street} c''è una macchina che brucia, si vede il fumo da lontano.","panic":"Pronto, c''è un''auto in fiamme in {location.street}!"},"variables":{"location":{"pool":"stradario","zones":["residenziale","industriale","colline"],"floor":[0,0]},"sc":{"choice":[{"w":"È parcheggiata sotto casa, escono fiamme dal cofano… ci sono altre macchine vicino!","wd":"Auto parcheggiata, fiamme dal cofano, altre auto vicine","p":"No, dentro non c''è nessuno.","pd":"Nessuno a bordo","ag":["115"],"event":"incendio_tecnico.incendio_veicolo"},{"w":"È andata a sbattere contro il guardrail e ha preso fuoco! Il conducente è uscito da solo.","wd":"Incidente contro il guardrail, auto in fiamme","p":"Il conducente è fuori, dice che sta bene, solo spaventato.","pd":"Conducente uscito, illeso","ag":["115","{location.police}"],"event":"incendio_tecnico.incendio_veicolo"},{"w":"C''è fumo dappertutto dentro la macchina, è ferma in mezzo alla strada!","wd":"Fumo nell''abitacolo, auto ferma in carreggiata","p":"C''è un uomo dentro! Non riesce ad aprire la portiera!","pd":"Uomo bloccato a bordo","ag":["115","118"],"event":"incendio_tecnico.incendio_veicolo"}],"weights":[45,30,25]}},"caller":{"gender":"any","phone_type":"mobile","panic_start":55,"ring_patience_s":35,"hold_patience_s":30,"reliability":0.95,"callback_chance":0.3},"opening":{"calm":"Pronto, c''è una macchina che sta prendendo fuoco!","panic":"Pronto! Una macchina in fiamme, presto!"},"facts":{"indirizzo":{"display":"{location.street}, vicino a {location.landmark} ({location.zone_name})"},"incendio":{"display":"{sc.wd}"},"persone":{"display":"{sc.pd}"}},"nodes":[{"id":"q_dove","label":"Dove si trova l''auto? Via e un punto di riferimento.","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":"In {location.street}, vicino a {location.landmark}.","panic":"{location.street}! Vicino a {location.landmark}!"},"error":{"threshold":65,"chance":0.4,"fact":"indirizzo","display":"{location.street_wrong} (incerto)","reply":{"panic":"In {location.street_wrong}… credo, non ne sono sicuro!"}}},{"id":"q_cosa","label":"Cosa vede esattamente? Dove sono le fiamme?","cost_s":6,"reveals":["incendio"],"reply":{"calm":"{sc.w}","panic":"{sc.w}"}},{"id":"q_persone","label":"C''è qualcuno dentro o vicino all''auto?","cost_s":5,"reveals":["persone"],"reply":{"calm":"{sc.p}","panic":"{sc.p}"}},{"id":"a_rassicura","type":"reassure","label":"Si allontani di almeno cinquanta metri e tenga lontani i curiosi: il serbatoio può esplodere.","cost_s":6,"panic_delta":-12,"reply":{"calm":"D''accordo, mi allontano.","panic":"Ok! Ci allontaniamo!"}}],"truth":{"event_type":"{sc.event}","agencies_required":"{sc.ag}","agencies_acceptable":["PS","CC"],"severity":{"optimal_s":240,"acceptable_s":480,"limit_s":1200},"critical_facts":["indirizzo","persone"],"hint_debrief":"Un''auto in fiamme è un lavoro per i Vigili del fuoco; se c''è qualcuno bloccato a bordo serve anche il 118, se c''è stato un incidente le forze dell''ordine."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('INC_029', 'Odore di gas', 'incendio_tecnico', 1, 4, 100, 1, 'mattina,pomeriggio,sera,notte', 0, 0, '{"code":"INC_029","title":"Odore di gas","category":"incendio_tecnico","phase":1,"difficulty":4,"weight":100,"min_rank":1,"time_bands":["mattina","pomeriggio","sera","notte"],"lang":"it","variables":{"location":{"pool":"stradario","zones":["centro","residenziale"],"floor":[0,4]},"sc":{"choice":[{"w":"Sul pianerottolo c''è un odore fortissimo, viene dalla porta del signor Bruno. Ho suonato ma non apre.","wd":"Forte odore dall''appartamento di un vicino anziano che non apre","p":"Lui dovrebbe essere in casa, esce sempre solo la mattina.","pd":"Anziano probabilmente in casa, non risponde","ag":["115","118"]},{"w":"In cucina, vicino al fornello. Ho già chiuso la manopola del gas centrale.","wd":"Odore in cucina, rubinetto generale già chiuso","p":"Siamo io e mia figlia, stiamo bene.","pd":"Due persone, nessun sintomo","ag":["115"]},{"w":"C''è un cantiere qui davanti, la ruspa ha rotto un tubo, sento il gas che fischia!","wd":"Tubo del gas tranciato da una ruspa, fuga udibile","p":"Gli operai si sono allontanati, ma ci sono le case e il traffico.","pd":"Nessun ferito, abitazioni e traffico vicini","ag":["115","{location.police}"]}]}},"caller":{"gender":"any","phone_type":"any","panic_start":45,"ring_patience_s":35,"hold_patience_s":30,"reliability":0.95,"callback_chance":0.6},"opening":{"calm":"Buonasera, c''è un forte odore di gas, non so cosa fare.","panic":"Pronto, c''è puzza di gas dappertutto!"},"facts":{"indirizzo":{"display":"{location.street} {location.number}, {location.zone_name}"},"fonte":{"label":"Da dove viene","display":"{sc.wd}"},"persone":{"display":"{sc.pd}"}},"nodes":[{"id":"q_dove","label":"Mi dica l''indirizzo: via e numero civico.","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":"{location.street} {location.number}.","panic":"{location.street}… il {location.number}!"},"error":{"threshold":65,"chance":0.4,"fact":"indirizzo","display":"{location.street} {location.number_wrong}, {location.zone_name}","reply":{"panic":"{location.street}… il {location.number_wrong}!"}}},{"id":"q_dove_odore","label":"Dove sente l''odore esattamente?","cost_s":6,"reveals":["fonte"],"reply":{"calm":"{sc.w}","panic":"{sc.w}"}},{"id":"q_persone","label":"Ci sono persone coinvolte? Qualcuno si sente male?","cost_s":5,"reveals":["persone"],"reply":{"calm":"{sc.p}","panic":"{sc.p}"}},{"id":"a_istruzioni","type":"reassure","label":"Non accenda luci né interruttori, non usi il campanello, apra le finestre se può ed esca all''aperto.","cost_s":6,"panic_delta":-12,"reply":{"calm":"Va bene, non tocco niente ed esco.","panic":"Ok, esco subito!"}}],"truth":{"event_type":"incendio_tecnico.fuga_gas","agencies_required":"{sc.ag}","agencies_acceptable":["PS","CC"],"severity":{"optimal_s":240,"acceptable_s":600,"limit_s":1200},"critical_facts":["indirizzo","fonte"],"hint_debrief":"Nelle fughe di gas l''istruzione più importante è non azionare nulla di elettrico. Se qualcuno non risponde dentro casa serve anche il 118."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('INC_030', 'Incendio di sterpaglie o bosco', 'incendio_tecnico', 1, 4, 100, 1, 'mattina,pomeriggio,sera,notte', 1, 0, '{"code":"INC_030","title":"Incendio di sterpaglie o bosco","category":"incendio_tecnico","phase":1,"difficulty":4,"weight":100,"min_rank":1,"time_bands":["mattina","pomeriggio","sera","notte"],"lang":"it","can_duplicate":true,"duplicates":{"chance":0.4,"max":2,"delay_s":[40,200],"near_twin_chance":0.15},"witness_opening":{"calm":"Buonasera, si vede del fumo in collina, verso {location.landmark}.","panic":"Pronto, c''è un incendio in {location.street}, si vedono le fiamme!"},"variables":{"location":{"pool":"stradario","zones":["colline","montagna"],"floor":[0,0]},"sc":{"choice":[{"f":"Sterpaglie lungo la strada, un tratto di una ventina di metri.","fd":"Sterpaglie a bordo strada, circa 20 metri","v":"Poco vento, il fumo va verso il campo.","vd":"Poco vento, nessuna casa minacciata","p":"Nessuno, sono passato in macchina.","pd":"Nessuno coinvolto","ag":["115"]},{"f":"Il bosco sopra l''agriturismo! Si vedono le fiamme tra gli alberi.","fd":"Incendio nel bosco, fiamme visibili","v":"C''è vento forte e va verso le case!","vd":"Vento forte verso le abitazioni","p":"Nell''agriturismo ci sono i clienti, stanno uscendo.","pd":"Ospiti dell''agriturismo in evacuazione","ag":["115"]},{"f":"Stavo bruciando le potature nel mio campo e il fuoco mi è scappato verso la siepe.","fd":"Fuoco sfuggito da un abbruciamento di potature","v":"Un po'' di vento.","vd":"Vento moderato","p":"Ho provato a spegnerlo e mi sono bruciato le mani…","pd":"Il chiamante ha ustioni alle mani","ag":["115","118"]}]}},"caller":{"gender":"m","phone_type":"mobile","panic_start":45,"ring_patience_s":35,"hold_patience_s":30,"reliability":0.95,"callback_chance":0.6},"opening":{"calm":"Pronto, c''è un incendio qui in collina, c''è tanto fumo.","panic":"Pronto! Sta bruciando tutto, c''è un incendio!"},"facts":{"indirizzo":{"display":"{location.street}, vicino a {location.landmark} ({location.zone_name})"},"incendio":{"display":"{sc.fd}"},"pericoli":{"display":"{sc.vd}"},"persone":{"display":"{sc.pd}"}},"nodes":[{"id":"q_dove","label":"Dove si trova l''incendio? Strada, località, punto di riferimento.","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":"In {location.street}, vicino a {location.landmark}.","panic":"{location.street}! Verso {location.landmark}!"},"error":{"threshold":65,"chance":0.4,"fact":"indirizzo","display":"{location.street_wrong} (incerto)","reply":{"panic":"In {location.street_wrong}… credo, non ne sono sicuro!"}}},{"id":"q_cosa","label":"Cosa sta bruciando e quanto è esteso?","cost_s":6,"reveals":["incendio"],"reply":{"calm":"{sc.f}","panic":"{sc.f}"}},{"id":"q_vento","label":"C''è vento? Verso dove va il fuoco?","cost_s":5,"reveals":["pericoli"],"reply":{"calm":"{sc.v}","panic":"{sc.v}"}},{"id":"q_persone","label":"Ci sono persone o case in pericolo? Qualcuno si è ferito?","cost_s":6,"reveals":["persone"],"reply":{"calm":"{sc.p}","panic":"{sc.p}"}},{"id":"a_rassicura","type":"reassure","label":"Si allontani controvento e non provi a spegnerlo: aspetti i Vigili del fuoco in un punto sicuro.","cost_s":6,"panic_delta":-12,"reply":{"calm":"Va bene… grazie.","panic":"Sì… sì, va bene."}}],"truth":{"event_type":"incendio_tecnico.incendio_vegetazione","agencies_required":"{sc.ag}","agencies_acceptable":["CC"],"severity":{"optimal_s":300,"acceptable_s":600,"limit_s":1500},"critical_facts":["indirizzo","pericoli"],"hint_debrief":"Per un incendio di vegetazione contano vento e direzione: dicono se le case sono a rischio. Chi si è ustionato cercando di spegnerlo ha bisogno del 118."}}', 1, 1)
ON DUPLICATE KEY UPDATE
