INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('INC_035', 'Emergenza in un capannone', 'incendio_tecnico', 1, 6, 100, 1, 'mattina,pomeriggio,sera,notte', 1, 0, '{"code":"INC_035","title":"Emergenza in un capannone","category":"incendio_tecnico","phase":1,"difficulty":6,"weight":100,"min_rank":1,"time_bands":["mattina","pomeriggio","sera","notte"],"lang":"it","can_duplicate":true,"duplicates":{"chance":0.5,"max":2,"delay_s":[30,160],"near_twin_chance":0},"witness_opening":{"calm":"Buonasera, dalla zona artigianale si vede una colonna di fumo, verso {location.street}.","panic":"Pronto, c''è un fumo nero enorme in {location.street}!"},"variables":{"location":{"pool":"stradario","zones":["industriale"],"floor":[0,0]},"sc":{"choice":[{"w":"Esce un fumo nerissimo dal capannone della verniciatura!","wd":"Fumo nero dal reparto verniciatura","p":"Siamo usciti tutti, ma un collega tossisce tantissimo e non riesce a riprendersi.","pd":"Operaio con tosse persistente dopo il fumo","ag":["115","118"],"event":"incendio_tecnico.incendio_abitazione"},{"w":"Un camion nel piazzale ha perso un liquido, c''è una pozza enorme e un odore che brucia gli occhi.","wd":"Sversamento di liquido chimico da un camion, odore irritante","p":"Nessuno sta male, ci siamo allontanati.","pd":"Nessun ferito","ag":["115"],"event":"incendio_tecnico.sversamento"},{"w":"C''è stato uno scoppio in officina, adesso c''è fuoco vicino al compressore!","wd":"Esplosione in officina, fiamme vicino al compressore","p":"Un operaio è ustionato sulle braccia e sul viso!","pd":"Operaio ustionato a braccia e viso","ag":["115","118","CC"],"event":"incendio_tecnico.incendio_abitazione"}]}},"caller":{"gender":"m","phone_type":"mobile","panic_start":70,"ring_patience_s":35,"hold_patience_s":30,"reliability":0.95,"callback_chance":0.6},"opening":{"calm":"Pronto, chiamo dalla ditta, abbiamo un''emergenza nel capannone.","panic":"Pronto! Emergenza in ditta, presto!"},"facts":{"indirizzo":{"display":"{location.street} {location.number}, zona artigianale"},"evento":{"display":"{sc.wd}"},"persone":{"display":"{sc.pd}"},"sostanze":{"label":"Sostanze presenti","display":"Vernici e solventi in magazzino"}},"nodes":[{"id":"q_dove","label":"Qual è l''indirizzo dell''azienda?","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":"{location.street} {location.number}, entrate dal cancello principale.","panic":"{location.street} {location.number}!"},"error":{"threshold":65,"chance":0.4,"fact":"indirizzo","display":"{location.street} {location.number_wrong}, {location.zone_name}","reply":{"panic":"{location.street}… il {location.number_wrong}!"}}},{"id":"q_cosa","label":"Cosa sta succedendo esattamente?","cost_s":6,"reveals":["evento"],"reply":{"calm":"{sc.w}","panic":"{sc.w}"}},{"id":"q_persone","label":"Ci sono feriti o persone ancora dentro?","cost_s":6,"reveals":["persone"],"reply":{"calm":"{sc.p}","panic":"{sc.p}"}},{"id":"q_sostanze","label":"Sa che sostanze ci sono in quel capannone?","cost_s":5,"reveals":["sostanze"],"reply":{"calm":"Vernici, solventi… ci sono i fusti in magazzino.","panic":"Vernici, solventi… ci sono i fusti in magazzino."}},{"id":"a_rassicura","type":"reassure","label":"Fate uscire tutti, contateli al punto di raccolta e non avvicinatevi al fumo o al liquido.","cost_s":6,"panic_delta":-15,"reply":{"calm":"Va bene… grazie.","panic":"Sì… sì, va bene."}}],"truth":{"event_type":"{sc.event}","acceptable_event_types":["incendio_tecnico.sversamento","incendio_tecnico.incendio_abitazione","sanitaria.intossicazione"],"agencies_required":"{sc.ag}","agencies_acceptable":["CC","118"],"severity":{"optimal_s":240,"acceptable_s":480,"limit_s":1200},"critical_facts":["indirizzo","persone","sostanze"],"hint_debrief":"Negli incidenti industriali le sostanze presenti cambiano l''intervento dei Vigili del fuoco: vanno sempre chieste."}}', 1, 1)
