INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('INC_036', 'Cavo elettrico a terra', 'incendio_tecnico', 1, 4, 100, 1, 'mattina,pomeriggio,sera,notte', 0, 0, '{"code":"INC_036","title":"Cavo elettrico a terra","category":"incendio_tecnico","phase":1,"difficulty":4,"weight":100,"min_rank":1,"time_bands":["mattina","pomeriggio","sera","notte"],"lang":"it","variables":{"location":{"pool":"stradario","zones":["residenziale","industriale","colline"],"floor":[0,0]},"sc":{"choice":[{"w":"Un cavo della linea è caduto sul marciapiede e fa le scintille, vicino alla fermata del bus!","wd":"Cavo elettrico a terra con scintille vicino alla fermata","p":"Ho fermato le persone, nessuno l''ha toccato.","pd":"Nessuno coinvolto","ag":["115"]},{"w":"Un cavo è caduto col vento e un signore l''ha toccato… è a terra!","wd":"Cavo a terra, un uomo lo ha toccato","p":"È a terra e non si muove, non so se respira!","pd":"Uomo folgorato, a terra, non si muove","ag":["115","118"]},{"w":"Un camion ha preso un palo della luce, è piegato sopra la strada e i fili pendono!","wd":"Palo della luce piegato sulla strada dopo un urto","p":"L''autista è sceso, sta bene.","pd":"Autista illeso","ag":["115","{location.police}"]}]}},"caller":{"gender":"any","phone_type":"mobile","panic_start":50,"ring_patience_s":35,"hold_patience_s":30,"reliability":0.95,"callback_chance":0.6},"opening":{"calm":"Buonasera, c''è un cavo elettrico per terra, è pericoloso.","panic":"Pronto! C''è un cavo della corrente per terra!"},"facts":{"indirizzo":{"display":"{location.street}, vicino a {location.landmark} ({location.zone_name})"},"pericolo":{"label":"Situazione","display":"{sc.wd}"},"persone":{"display":"{sc.pd}"}},"nodes":[{"id":"q_dove","label":"Dove si trova? Via e punto di riferimento.","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":"In {location.street}, vicino a {location.landmark}.","panic":"{location.street}!"},"error":{"threshold":65,"chance":0.4,"fact":"indirizzo","display":"{location.street_wrong} (incerto)","reply":{"panic":"In {location.street_wrong}… credo, non ne sono sicuro!"}}},{"id":"q_cosa","label":"Cosa vede esattamente?","cost_s":6,"reveals":["pericolo"],"reply":{"calm":"{sc.w}","panic":"{sc.w}"}},{"id":"q_persone","label":"Qualcuno è stato colpito o è vicino al cavo?","cost_s":5,"reveals":["persone"],"reply":{"calm":"{sc.p}","panic":"{sc.p}"}},{"id":"a_distanza","type":"reassure","label":"Non si avvicini e non tocchi la persona finché la corrente non è staccata: tenga tutti ad almeno dieci metri.","cost_s":6,"panic_delta":-10,"reply":{"calm":"Va bene, stiamo lontani.","panic":"Ok! Nessuno si avvicina!"}}],"truth":{"event_type":"incendio_tecnico.danni_maltempo","acceptable_event_types":["sicurezza.pericolo_viabilita","incendio_tecnico.soccorso_persona"],"agencies_required":"{sc.ag}","agencies_acceptable":["PS","CC"],"severity":{"optimal_s":240,"acceptable_s":600,"limit_s":1200},"critical_facts":["indirizzo","persone"],"hint_debrief":"Con un cavo a terra la prima istruzione è la distanza: chi tocca una persona folgorata rischia di diventare la seconda vittima."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('INC_052', 'Canna fumaria in fiamme', 'incendio_tecnico', 1, 3, 100, 1, 'mattina,pomeriggio,sera,notte', 0, 0, '{"code":"INC_052","title":"Canna fumaria in fiamme","category":"incendio_tecnico","phase":1,"difficulty":3,"weight":100,"min_rank":1,"time_bands":["mattina","pomeriggio","sera","notte"],"lang":"it","variables":{"location":{"pool":"stradario","zones":["colline","residenziale","centro"],"floor":[0,2]},"sc":{"choice":[{"w":"Dal comignolo escono scintille e fiamme, il camino fa un rumore come un treno!","wd":"Fiamme e scintille dal comignolo","p":"Siamo usciti tutti in giardino.","pd":"Tutti fuori casa","ag":["115"]},{"w":"Il muro della camera vicino al camino è caldissimo e c''è fumo che esce dalle crepe.","wd":"Muro surriscaldato vicino alla canna fumaria, fumo dalle crepe","p":"Mia suocera è a letto, non cammina.","pd":"Anziana allettata in casa","ag":["115","118"]}],"weights":[60,40]}},"caller":{"gender":"any","phone_type":"any","panic_start":50,"ring_patience_s":35,"hold_patience_s":30,"reliability":0.95,"callback_chance":0.6},"opening":{"calm":"Buonasera, credo che stia bruciando la canna fumaria del camino.","panic":"Pronto! Il camino sta prendendo fuoco!"},"facts":{"indirizzo":{"display":"{location.street} {location.number}, {location.zone_name}"},"incendio":{"display":"{sc.wd}"},"persone":{"display":"{sc.pd}"}},"nodes":[{"id":"q_dove","label":"Mi dica l''indirizzo: via e numero civico.","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":"{location.street} {location.number}.","panic":"{location.street}… il {location.number}!"},"error":{"threshold":65,"chance":0.4,"fact":"indirizzo","display":"{location.street} {location.number_wrong}, {location.zone_name}","reply":{"panic":"{location.street}… il {location.number_wrong}!"}}},{"id":"q_cosa","label":"Cosa vede esattamente?","cost_s":6,"reveals":["incendio"],"reply":{"calm":"{sc.w}","panic":"{sc.w}"}},{"id":"q_persone","label":"Siete tutti fuori? C''è qualcuno che non può muoversi?","cost_s":5,"reveals":["persone"],"reply":{"calm":"{sc.p}","panic":"{sc.p}"}},{"id":"a_rassicura","type":"reassure","label":"Non buttate acqua nel camino: chiudete la presa d''aria se ci arrivate e uscite di casa.","cost_s":6,"panic_delta":-15,"reply":{"calm":"Va bene… grazie.","panic":"Sì… sì, va bene."}}],"truth":{"event_type":"incendio_tecnico.incendio_abitazione","agencies_required":"{sc.ag}","severity":{"optimal_s":300,"acceptable_s":600,"limit_s":1500},"critical_facts":["indirizzo","persone"],"hint_debrief":"Un incendio di canna fumaria può propagarsi al tetto. Chi non può uscire da solo richiede anche il 118."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('SAN_001', 'Anziana caduta in casa', 'sanitaria', 1, 1, 120, 1, 'mattina,pomeriggio,sera,notte', 0, 0, '{"code":"SAN_001","title":"Anziana caduta in casa","category":"sanitaria","phase":1,"difficulty":1,"weight":120,"min_rank":1,"time_bands":["mattina","pomeriggio","sera","notte"],"lang":"it","variables":{"location":{"pool":"stradario","zones":["centro","residenziale"],"floor":[0,4]},"injury":{"choice":[{"text":"Mi fa tanto male l''anca destra… la testa no, quella non l''ho battuta.","display":"Forte dolore all''anca destra, non ha battuto la testa"},{"text":"Ho battuto la testa sullo spigolo del tavolo… mi gira un po'' tutto.","display":"Ha battuto la testa, ha dei capogiri"},{"text":"Il polso… credo di essermelo rotto. La testa no.","display":"Dolore al polso, non ha battuto la testa"}]},"access":{"choice":[{"text":"No, sono sola. La porta è chiusa a chiave e le chiavi sono sul mobile dell''ingresso… non ci arrivo.","display":"Sola in casa, porta chiusa a chiave: non può aprire","agencies":["118","115"]},{"text":"Sono sola, ma la signora del piano di sopra ha le chiavi, può aprire lei.","display":"Sola; la vicina del piano di sopra ha le chiavi","agencies":["118"]},{"text":"C''è mio nipote, l''ho mandato giù ad aprire il portone.","display":"C''è il nipote, che aprirà ai soccorsi","agencies":["118"]}],"weights":[40,35,25]}},"caller":{"gender":"f","phone_type":"any","panic_start":30,"ring_patience_s":45,"hold_patience_s":70,"reliability":0.9,"callback_chance":0.7},"opening":{"calm":"Pronto? Scusi… sono caduta in cucina e non riesco più ad alzarmi.","panic":"Pronto?! Aiuto… sono caduta, non riesco ad alzarmi, mi fa male!"},"facts":{"indirizzo":{"display":"{location.street} {location.number}, {location.zone_name}"},"piano":{"display":"{location.floor_text}, campanello {caller_surname}"},"evento":{"display":"Scivolata in cucina, non riesce ad alzarsi"},"ferite":{"display":"{injury.display}"},"accesso":{"label":"Accesso all''abitazione","display":"{access.display}"}},"nodes":[{"id":"q_dove","label":"Mi dica l''indirizzo: via e numero civico.","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":"Abito in {location.street} {location.number}.","panic":"In {location.street}… il {location.number}, sì, il {location.number}."},"error":{"threshold":101,"fact":"indirizzo","display":"{location.street} {location.number_wrong}, {location.zone_name}","reply":{"calm":"In {location.street} {location.number_wrong}… sì, mi pare."}}},{"id":"q_piano","label":"A che piano abita? Che nome c''è sul campanello?","cost_s":5,"requires":["q_dove"],"reveals":["piano"],"reply":{"calm":"Al {location.floor_text}. Sul campanello c''è scritto {caller_surname}.","panic":"{location.floor_text}… {caller_surname}, c''è scritto {caller_surname}!"}},{"id":"q_cosa","label":"Mi racconti cosa è successo.","cost_s":7,"reveals":["evento"],"reply":{"calm":"Stavo prendendo un piatto, sono scivolata e sono finita per terra. Adesso non riesco a tirarmi su.","panic":"Sono scivolata! Sono per terra e non riesco ad alzarmi!"}},{"id":"q_dolore","label":"Ha male da qualche parte? Ha sbattuto la testa?","cost_s":7,"requires":["q_cosa"],"reveals":["ferite"],"reply":{"calm":"{injury.text}","panic":"{injury.text}"}},{"id":"q_accesso","label":"C''è qualcuno con lei? Chi può aprire la porta ai soccorsi?","cost_s":7,"reveals":["accesso"],"reply":{"calm":"{access.text}","panic":"{access.text}"}},{"id":"a_rassicura","type":"reassure","label":"Signora, non si muova e stia tranquilla: le mando subito aiuto.","cost_s":6,"panic_delta":-20,"reply":{"calm":"Va bene… grazie, grazie tanto.","panic":"Sì… sì, va bene. Faccia presto però."}}],"truth":{"event_type":"sanitaria.trauma_caduta","agencies_required":["{access.agencies}"],"severity":{"optimal_s":300,"acceptable_s":900,"limit_s":2400},"critical_facts":["indirizzo","accesso"],"hint_debrief":"Una persona sola che non può aprire la porta richiede anche i Vigili del fuoco per l''accesso: senza, l''ambulanza resta fuori."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('SAN_007', 'Non si sveglia (arresto cardiaco mascherato)', 'sanitaria', 1, 3, 90, 1, 'mattina,pomeriggio,sera,notte', 0, 0, '{"code":"SAN_007","title":"Non si sveglia (arresto cardiaco mascherato)","category":"sanitaria","phase":1,"difficulty":3,"weight":90,"min_rank":1,"time_bands":["mattina","pomeriggio","sera","notte"],"lang":"it","variables":{"location":{"pool":"stradario","zones":["centro","residenziale","colline"],"floor":[0,5]},"patient":{"choice":[{"rel":"marito","my":"Mio marito","him":"lo"},{"rel":"compagno","my":"Il mio compagno","him":"lo"},{"rel":"papà","my":"Mio papà","him":"lo"}]},"patient_age":{"range":[58,79]}},"caller":{"gender":"f","phone_type":"any","panic_start":65,"ring_patience_s":30,"hold_patience_s":20,"reliability":0.95,"callback_chance":0.9},"opening":{"calm":"Pronto? {patient.my} non si sveglia… sembra che dorma ma non mi risponde.","panic":"Pronto?! {patient.my} non si sveglia, non mi risponde! Faccia presto!"},"facts":{"indirizzo":{"display":"{location.street} {location.number}, {location.zone_name}"},"piano":{"display":"{location.floor_text}, citofono {caller_surname}"},"coscienza":{"display":"Non risponde e non reagisce quando lo scuote"},"respiro":{"display":"Fa dei rantoli ogni tanto, «come se russasse»"},"eta":{"display":"{patient_age} anni"},"pericoli":{"display":"Nessun odore di gas o fumo"}},"nodes":[{"id":"q_dove","label":"Mi dica l''indirizzo esatto.","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":"{location.street} {location.number}.","panic":"{location.street}… il {location.number}! Venite!"},"error":{"threshold":60,"chance":0.5,"fact":"indirizzo","display":"{location.street} {location.number_wrong}, {location.zone_name}","reply":{"panic":"{location.street}… il {location.number_wrong}! Faccia presto!"}}},{"id":"q_piano","label":"Che piano? Che nome c''è sul citofono?","cost_s":5,"requires":["q_dove"],"reveals":["piano"],"reply":{"calm":"Al {location.floor_text}, citofono {caller_surname}.","panic":"{location.floor_text}! {caller_surname}!"}},{"id":"q_coscienza","label":"Lo chiami forte e lo scuota per le spalle. Risponde?","cost_s":10,"panic_delta":5,"reveals":["coscienza"],"reply":{"calm":"No… non risponde, niente.","panic":"No! Non fa niente! Oddio!"}},{"id":"q_respiro","label":"Guardi il petto: respira normalmente?","cost_s":10,"requires":["q_coscienza"],"reveals":["respiro"],"reply":{"calm":"Fa… tipo dei rantoli, ogni tanto. Come se russasse.","panic":"Fa un rumore strano… tipo russare…"},"error":{"threshold":70,"chance":0.6,"fact":"respiro","display":"Dice che respira normalmente","reply":{"panic":"Sì, sì, respira! Cioè… credo di sì!"}}},{"id":"q_eta","label":"Quanti anni ha?","cost_s":4,"reveals":["eta"],"reply":{"calm":"{patient_age}.","panic":"{patient_age}, credo… sì, {patient_age}!"}},{"id":"q_pericoli","label":"Sente odore di gas o fumo in casa?","cost_s":5,"reveals":["pericoli"],"reply":{"calm":"No, niente.","panic":"No! Ma cosa c''entra?!"}},{"id":"a_rassicura","type":"reassure","label":"Signora, la sto aiutando. Respiri con me e mi segua.","cost_s":8,"panic_delta":-25,"reply":{"calm":"Sì… sì, va bene.","panic":"Va bene… va bene, ci provo."}}],"truth":{"event_type":"sanitaria.arresto_cardiaco","agencies_required":["118"],"agencies_acceptable":[],"severity":{"optimal_s":60,"acceptable_s":150,"limit_s":300},"critical_facts":["indirizzo","coscienza","respiro"],"hint_debrief":"«Dorme ma non risponde» + «fa un rumore strano» indica un respiro agonico: va trasferito come arresto cardiaco appena confermati coscienza e respiro assenti."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('SAN_008', 'Dolore al petto minimizzato', 'sanitaria', 1, 4, 90, 1, 'mattina,pomeriggio,sera,notte', 0, 0, '{"code":"SAN_008","title":"Dolore al petto minimizzato","category":"sanitaria","phase":1,"difficulty":4,"weight":90,"min_rank":1,"time_bands":["mattina","pomeriggio","sera","notte"],"lang":"it","variables":{"location":{"pool":"stradario","zones":["centro","residenziale","colline"],"floor":[0,4]},"rad":{"choice":[{"text":"Beh… sì, un po'' anche sul braccio sinistro. E sudo freddo, ma sarà il caldo.","display":"Dolore che va al braccio sinistro, sudore freddo"},{"text":"No, sta qui in mezzo… però mi manca un po'' il fiato quando parlo.","display":"Dolore al centro del petto, affanno quando parla"}]},"patient_age":{"range":[56,74]}},"caller":{"gender":"m","phone_type":"any","panic_start":12,"ring_patience_s":50,"hold_patience_s":60,"reliability":0.85,"callback_chance":0.4},"opening":{"calm":"Buonasera, scusate il disturbo, niente di grave… ho un peso sullo stomaco da un paio d''ore, volevo sapere se posso prendere qualcosa.","panic":"Buonasera… scusate, ho un peso qui sul petto che non passa, volevo sapere cosa prendere."},"facts":{"dolore":{"label":"Sintomo","display":"Peso al centro del petto da circa due ore, «ma passa»"},"irradiazione":{"label":"Irradiazione","display":"{rad.display}"},"anamnesi":{"label":"Precedenti","display":"Due anni fa gli hanno messo uno stent"},"eta":{"display":"{patient_age} anni"},"indirizzo":{"display":"{location.street} {location.number}, {location.zone_name}"},"accesso":{"display":"Solo in casa, dice di poter aprire"}},"nodes":[{"id":"q_sintomi","label":"Mi descriva il fastidio: dove lo sente e da quanto tempo?","cost_s":8,"reveals":["dolore"],"reply":{"calm":"Qui in mezzo al petto, tipo un peso. Da un paio d''ore… ma va e viene, eh.","panic":"In mezzo al petto, un peso… da due ore."}},{"id":"q_irradia","label":"Il dolore va verso il braccio, il collo o la mandibola? Suda?","cost_s":7,"requires":["q_sintomi"],"reveals":["irradiazione"],"reply":{"calm":"{rad.text}","panic":"{rad.text}"},"error":{"threshold":101,"fact":"irradiazione","display":"Dice che il dolore resta fermo, nessun altro sintomo","reply":{"calm":"No no, niente, sta fermo lì. Sto bene, davvero."}}},{"id":"q_storia","label":"Ha mai avuto problemi di cuore?","cost_s":5,"reveals":["anamnesi"],"reply":{"calm":"Mah, due anni fa mi hanno messo uno stent… ma da allora niente.","panic":"Uno stent, due anni fa…"}},{"id":"q_eta","label":"Quanti anni ha?","cost_s":3,"reveals":["eta"],"reply":{"calm":"{patient_age}.","panic":"{patient_age}."}},{"id":"q_dove","label":"Mi dica l''indirizzo da cui chiama.","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":"Sono a casa, in {location.street} {location.number}. Ma non serve che mandiate qualcuno, eh.","panic":"{location.street} {location.number}."}},{"id":"q_accesso","label":"È solo? Riesce ad aprire la porta?","cost_s":5,"reveals":["accesso"],"reply":{"calm":"Sì, mia moglie è dalla sorella. Apro io, figurarsi.","panic":"Sono solo… apro io."}},{"id":"a_riposo","type":"reassure","label":"Si sieda, non faccia sforzi e apra la porta di casa: le mando un''ambulanza per sicurezza.","cost_s":7,"panic_delta":-5,"reply":{"calm":"Addirittura l''ambulanza? Va bene… se dice lei.","panic":"Va bene… grazie."}}],"truth":{"event_type":"sanitaria.dolore_toracico","acceptable_event_types":["sanitaria.malore"],"agencies_required":["118"],"severity":{"optimal_s":300,"acceptable_s":600,"limit_s":1200},"critical_facts":["dolore","indirizzo"],"hint_debrief":"Chi minimizza va preso sul serio: un peso al petto da ore, oltre i 50 anni e con uno stent alle spalle, è un''emergenza fino a prova contraria."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('SAN_010', 'Turista straniera, marito colto da malore', 'sanitaria', 1, 5, 70, 2, 'mattina,pomeriggio,sera', 0, 0, '{"code":"SAN_010","title":"Turista straniera, marito colto da malore","category":"sanitaria","phase":1,"difficulty":5,"weight":70,"min_rank":2,"time_bands":["mattina","pomeriggio","sera"],"lang":"it","variables":{"location":{"pool":"stradario","zones":["centro"],"floor":[1,3]},"patient_age":{"range":[64,79]}},"caller":{"gender":"f","first_pool":"names_de_f","surname_pool":"surnames_de","phone_type":"mobile","panic_start":72,"ring_patience_s":35,"hold_patience_s":20,"reliability":0.9,"callback_chance":0.7},"opening":{"calm":"Hello? Hallo? Please… my husband… he fall, now he speak not good!","panic":"Hallo?! Hilfe! Please, my husband, he fall, he speak strange!"},"facts":{"indirizzo":{"display":"Albergo in {location.street} {location.number}, {location.floor_text}"},"evento":{"display":"Il marito è caduto in bagno, parla male, un lato della bocca è storto"},"coscienza":{"display":"Sveglio, apre gli occhi, ma non riesce a parlare bene"},"eta":{"display":"{patient_age} anni"}},"nodes":[{"id":"a_interprete","label":"Attivare il servizio di interpretariato (tedesco).","cost_s":20,"panic_delta":-15,"sets_flag":"interprete","hidden_if_flag":"interprete","reply":{"calm":"(interprete in linea) La signora si chiama {caller_first}, è tedesca, in vacanza con il marito. Traduco io.","panic":"(interprete in linea) La signora è molto agitata, si chiama {caller_first}. Traduco io."}},{"id":"q_dove","label":"Where are you? Dove vi trovate?","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":"Hotel… near {location.landmark}! I don''t know the street!","panic":"Hotel! Near… {location.landmark}! Please!"},"reply_flag":{"flag":"interprete","calm":"(interprete) Sono in albergo, in {location.street} {location.number}, camera al {location.floor_text}.","panic":"(interprete) Albergo in {location.street} {location.number}, al {location.floor_text}."},"error":{"unless_flag":"interprete","threshold":0,"chance":1,"fact":"indirizzo","display":"Un albergo «vicino a {location.landmark}», via sconosciuta","reply":{"calm":"Hotel… near {location.landmark}! I don''t know the street!","panic":"Hotel! Near… {location.landmark}! Please!"}}},{"id":"q_cosa","label":"What happened? Cosa è successo?","cost_s":7,"reveals":["evento"],"reply":{"calm":"He fall in bathroom… now his words are wrong, his face… strange!","panic":"He fall! His face, his words… falsch, alles falsch!"},"reply_flag":{"flag":"interprete","calm":"(interprete) È caduto in bagno. Ora parla in modo confuso e ha la bocca storta da un lato.","panic":"(interprete) Caduto in bagno, parla male, la bocca è storta da una parte."},"error":{"unless_flag":"interprete","threshold":0,"chance":1,"fact":"evento","display":"Caduto in bagno, «parole sbagliate, faccia strana» (inglese stentato)","reply":{"calm":"He fall in bathroom… now his words are wrong, his face… strange!","panic":"He fall! His face, his words… falsch, alles falsch!"}}},{"id":"q_coscienza","label":"Is he awake? È sveglio, le risponde?","cost_s":6,"reveals":["coscienza"],"reply":{"calm":"Yes, eyes open… but he cannot say words.","panic":"Yes… yes, but no words!"},"reply_flag":{"flag":"interprete","calm":"(interprete) Sì, è sveglio e la guarda, ma non riesce a parlare bene.","panic":"(interprete) È sveglio ma non riesce a parlare."}},{"id":"q_eta","label":"How old is he? Quanti anni ha?","cost_s":4,"reveals":["eta"],"reply":{"calm":"{patient_age}.","panic":"{patient_age}!"}},{"id":"a_calma","type":"reassure","label":"Help is coming. Stay with him. / Arrivano i soccorsi, resti con lui.","cost_s":6,"panic_delta":-15,"reply":{"calm":"Okay… okay, danke.","panic":"Okay… please hurry!"}}],"truth":{"event_type":"sanitaria.ictus","acceptable_event_types":["sanitaria.malore","sanitaria.trauma_caduta"],"agencies_required":["118"],"severity":{"optimal_s":300,"acceptable_s":600,"limit_s":1500},"critical_facts":["indirizzo","evento"],"hint_debrief":"Parola alterata e bocca storta sono segni di ictus: conta ogni minuto. L''interprete costa 20 secondi, ma senza di lui l''indirizzo resta «un albergo vicino a…»."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('SAN_012', 'Escursionista ferito, batteria scarica', 'sanitaria', 1, 6, 70, 2, 'mattina,pomeriggio,sera', 0, 0, '{"code":"SAN_012","title":"Escursionista ferito, batteria scarica","category":"sanitaria","phase":1,"difficulty":6,"weight":70,"min_rank":2,"time_bands":["mattina","pomeriggio","sera"],"lang":"it","drop_after_s":[50,80],"variables":{"location":{"pool":"stradario","zones":["montagna"],"floor":[0,0]},"weather":{"choice":[{"text":"Sta calando il sole e tira un vento gelido.","display":"Sta facendo buio, vento freddo"},{"text":"C''è ancora luce, ma da ovest arriva un temporale.","display":"Luce per ora, temporale in arrivo"}]}},"caller":{"gender":"m","phone_type":"mobile","panic_start":45,"ring_patience_s":40,"hold_patience_s":15,"reliability":0.95,"callback_chance":0.3},"opening":{"calm":"Pronto? Sono in montagna, mi sono fatto male a una caviglia e non riesco a camminare… ho il telefono al 3 per cento.","panic":"Pronto?! Sono bloccato in montagna, la caviglia… non cammino, e il telefono si sta spegnendo!"},"facts":{"indirizzo":{"display":"{location.street}, dopo {location.landmark}"},"ferite":{"display":"Caviglia gonfia e deformata, non riesce ad appoggiare il piede"},"pericoli":{"display":"{weather.display}"},"persone":{"display":"Da solo"}},"nodes":[{"id":"q_dove","label":"Dove si trova? Che sentiero, cosa ha passato per ultimo?","cost_s":8,"reveals":["indirizzo"],"reply":{"calm":"Sono sul {location.street}, ho passato {location.landmark} una mezz''ora fa.","panic":"{location.street}… dopo {location.landmark}!"}},{"id":"q_ferite","label":"Com''è la caviglia? Riesce ad appoggiare il piede?","cost_s":6,"reveals":["ferite"],"reply":{"calm":"È gonfia e storta, non riesco proprio ad appoggiarla.","panic":"No! È storta, non la appoggio!"}},{"id":"q_meteo","label":"Com''è il tempo lì? Sta facendo buio?","cost_s":5,"reveals":["pericoli"],"reply":{"calm":"{weather.text}","panic":"{weather.text}"}},{"id":"q_solo","label":"È da solo?","cost_s":3,"reveals":["persone"],"reply":{"calm":"Sì, da solo.","panic":"Sì!"}},{"id":"a_batteria","type":"reassure","label":"Resti fermo dov''è, si copra e spenga tutto sul telefono tranne le chiamate: la troviamo noi.","cost_s":6,"panic_delta":-15,"reply":{"calm":"Ok. Resto qui.","panic":"Ok… ok, faccio così."}}],"truth":{"event_type":"sanitaria.soccorso_impervio","acceptable_event_types":["sanitaria.trauma_caduta","incendio_tecnico.soccorso_persona"],"agencies_required":["118"],"agencies_acceptable":["CC","115"],"severity":{"optimal_s":900,"acceptable_s":1800,"limit_s":3600},"critical_facts":["indirizzo","ferite"],"hint_debrief":"Con la batteria agli ultimi minuti la priorità è il luogo: poche domande mirate e trasferimento prima che la linea cada. Il cerchio AML in montagna è ampio: il punto di riferimento conta."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('SAN_014', 'Bambino: la mamma non si sveglia', 'sanitaria', 1, 7, 65, 2, 'mattina,pomeriggio,sera', 0, 0, '{"code":"SAN_014","title":"Bambino: la mamma non si sveglia","category":"sanitaria","phase":1,"difficulty":7,"weight":65,"min_rank":2,"time_bands":["mattina","pomeriggio","sera"],"lang":"it","variables":{"location":{"pool":"stradario","zones":["residenziale","centro","colline"],"floor":[0,4]},"kid_age":{"range":[6,9]},"mom":{"choice":[{"text":"Ha aperto un po'' gli occhi… ma non mi risponde bene.","display":"Apre appena gli occhi, non risponde bene"},{"text":"No… non si muove…","display":"Non si muove"}]}},"caller":{"gender":"any","phone_type":"landline","panic_start":55,"ring_patience_s":25,"hold_patience_s":8,"reliability":0.7,"callback_chance":0.5},"opening":{"calm":"Pronto?… La mamma è caduta per terra e non si sveglia…","panic":"Pronto?! La mamma… la mamma non si sveglia! (piange)"},"facts":{"chiamante":{"label":"Chi chiama","display":"{caller_first}, {kid_age} anni"},"coscienza":{"display":"{mom.display}"},"respiro":{"display":"«La pancia si alza e si abbassa»"},"indirizzo":{"display":"Non ricorda la via: «vicino a {location.landmark}»"},"persone":{"display":"Solo in casa con la mamma; la vicina del piano di sopra è in casa"},"farmaci":{"label":"Terapie","display":"La mamma fa «le punture per lo zucchero»"}},"nodes":[{"id":"q_nome","label":"Come ti chiami? Quanti anni hai?","cost_s":5,"panic_delta":-10,"reveals":["chiamante"],"reply":{"calm":"{caller_first}… ho {kid_age} anni.","panic":"{caller_first}… (singhiozza) {kid_age}…"}},{"id":"q_mamma","label":"Chiama forte la mamma e toccale la spalla. Si muove?","cost_s":9,"reveals":["coscienza"],"reply":{"calm":"{mom.text}","panic":"{mom.text}"}},{"id":"q_respiro","label":"Guarda la pancia della mamma: si alza e si abbassa?","cost_s":8,"requires":["q_mamma"],"reveals":["respiro"],"reply":{"calm":"Sì… si muove su e giù.","panic":"Sì… sì, si muove."}},{"id":"q_dove","label":"Sai dirmi dove abiti? Come si chiama la tua via?","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":"Abito vicino a {location.landmark}… la via non me la ricordo.","panic":"Non lo so! Vicino a {location.landmark}…"}},{"id":"q_adulti","label":"C''è un altro grande in casa? Un vicino che conosci?","cost_s":6,"reveals":["persone"],"reply":{"calm":"Papà è al lavoro. La signora di sopra c''è, ha il cane.","panic":"No… la signora di sopra forse."}},{"id":"q_farmaci","label":"La mamma prende delle medicine? Fa delle punture?","cost_s":6,"reveals":["farmaci"],"reply":{"calm":"Sì, fa le punture per lo zucchero. Sulla pancia.","panic":"Le punture… per lo zucchero…"}},{"id":"a_bravo","type":"reassure","label":"Sei bravissimo. Resta vicino alla mamma: sto mandando qualcuno ad aiutarvi.","cost_s":6,"panic_delta":-22,"reply":{"calm":"Va bene… resto qui con lei.","panic":"Va bene… (tira su col naso)"}}],"truth":{"event_type":"sanitaria.incosciente","acceptable_event_types":["sanitaria.malore"],"agencies_required":["118"],"severity":{"optimal_s":300,"acceptable_s":600,"limit_s":1200},"critical_facts":["indirizzo","coscienza"],"hint_debrief":"Un bambino non sa dare l''indirizzo: con la linea fissa l''indirizzo di intestazione è decisivo. Non metterlo in attesa: riattacca dopo pochi secondi. Le «punture per lo zucchero» fanno pensare a un''ipoglicemia."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('SAN_016', 'Difficoltà respiratoria', 'sanitaria', 1, 3, 100, 1, 'mattina,pomeriggio,sera,notte', 0, 0, '{"code":"SAN_016","title":"Difficoltà respiratoria","category":"sanitaria","phase":1,"difficulty":3,"weight":100,"min_rank":1,"time_bands":["mattina","pomeriggio","sera","notte"],"lang":"it","variables":{"location":{"pool":"stradario","zones":["centro","residenziale","colline"],"floor":[0,4]},"sc":{"choice":[{"open":"Pronto, mio figlio ha l''asma, ha usato lo spray due volte ma respira sempre peggio, fischia tutto.","cosa":"Figlio asmatico: peggiora nonostante due dosi di spray","resp_t":"Parla a fatica, una parola per volta… e le labbra sono un po'' scure.","resp":"Parla a monosillabi, labbra scure","event":"sanitaria.difficolta_respiratoria","acc":["sanitaria.reazione_allergica"],"sev":{"optimal_s":240,"acceptable_s":480,"limit_s":1200}},{"open":"Pronto! Mia moglie ha mangiato dei gamberetti… adesso ha la faccia gonfia e respira male!","cosa":"Dopo aver mangiato crostacei: viso gonfio, respira male","resp_t":"Dice che le si chiude la gola… ha delle chiazze rosse su tutto il collo.","resp":"Sensazione di gola che si chiude, chiazze rosse","event":"sanitaria.reazione_allergica","acc":["sanitaria.difficolta_respiratoria"],"sev":{"optimal_s":180,"acceptable_s":360,"limit_s":900}},{"open":"Aiuto! Mio papà stava mangiando e si è bloccato, non respira, sta diventando viola!","cosa":"Si è bloccato mangiando: probabile ostruzione da cibo","resp_t":"Non esce aria! Si tiene la gola con le mani e non riesce a tossire!","resp":"Non passa aria, non riesce a tossire","event":"sanitaria.difficolta_respiratoria","acc":["sanitaria.arresto_cardiaco"],"sev":{"optimal_s":60,"acceptable_s":150,"limit_s":360}},{"open":"Buonasera, mio marito ha l''enfisema… stanotte respira peggio del solito, è molto affannato.","cosa":"Malato cronico ai polmoni, affanno peggiorato stanotte","resp_t":"Parla, ma deve fermarsi ogni poco per prendere fiato. Ha l''ossigeno ma non basta.","resp":"Parla a frasi brevi, l''ossigeno di casa non basta","event":"sanitaria.difficolta_respiratoria","acc":[],"sev":{"optimal_s":420,"acceptable_s":900,"limit_s":1800}}]}},"caller":{"gender":"any","phone_type":"any","panic_start":60,"ring_patience_s":30,"hold_patience_s":20,"reliability":0.95,"callback_chance":0.6},"opening":{"calm":"{sc.open}","panic":"{sc.open}"},"facts":{"indirizzo":{"display":"{location.street} {location.number}, {location.zone_name}"},"piano":{"display":"{location.floor_text}, campanello {caller_surname}"},"evento":{"display":"{sc.cosa}"},"respiro":{"display":"{sc.resp}"}},"nodes":[{"id":"q_dove","label":"Mi dica l''indirizzo: via e numero civico.","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":"{location.street} {location.number}.","panic":"{location.street}… il {location.number}!"},"error":{"threshold":65,"chance":0.4,"fact":"indirizzo","display":"{location.street} {location.number_wrong}, {location.zone_name}","reply":{"panic":"{location.street}… il {location.number_wrong}!"}}},{"id":"q_piano","label":"A che piano? Che nome c''è sul campanello?","cost_s":5,"reveals":["piano"],"reply":{"calm":"Al {location.floor_text}, {caller_surname}.","panic":"Al {location.floor_text}, {caller_surname}."},"requires":["q_dove"]},{"id":"q_cosa","label":"Mi racconti cosa è successo e da quando.","cost_s":7,"reveals":["evento"],"reply":{"calm":"{sc.cosa}.","panic":"{sc.cosa}."}},{"id":"q_parla","label":"Riesce a parlare? Di che colore sono le labbra?","cost_s":7,"reveals":["respiro"],"reply":{"calm":"{sc.resp_t}","panic":"{sc.resp_t}"}},{"id":"a_rassicura","type":"reassure","label":"Lo tenga seduto, un po'' in avanti, e resti con lui: l''ambulanza è in arrivo.","cost_s":6,"panic_delta":-15,"reply":{"calm":"Va bene… grazie.","panic":"Sì… sì, va bene."}}],"truth":{"event_type":"{sc.event}","acceptable_event_types":"{sc.acc}","agencies_required":["118"],"severity":"{sc.sev}","critical_facts":["indirizzo","respiro"],"hint_debrief":"Nelle difficoltà respiratorie la domanda chiave è se la persona riesce a parlare: chi non riesce a dire una frase intera è grave."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('SAN_017', 'Parto in casa', 'sanitaria', 1, 4, 100, 1, 'mattina,pomeriggio,sera,notte', 0, 0, '{"code":"SAN_017","title":"Parto in casa","category":"sanitaria","phase":1,"difficulty":4,"weight":100,"min_rank":1,"time_bands":["mattina","pomeriggio","sera","notte"],"lang":"it","variables":{"location":{"pool":"stradario","zones":["centro","residenziale","colline"],"floor":[0,4]},"sc":{"choice":[{"c":"Ogni otto, dieci minuti. Le acque non si sono rotte.","cd":"Contrazioni ogni 8-10 minuti, acque integre","f":"È il primo.","fd":"Primo figlio","s":"No, dice di no.","sd":"Nessuna spinta","sev":{"optimal_s":900,"acceptable_s":1800,"limit_s":3600}},{"c":"Ogni due minuti! E si sono rotte le acque mezz''ora fa!","cd":"Contrazioni ogni 2 minuti, acque rotte","f":"È il terzo… gli altri due sono nati velocissimi!","fd":"Terzo figlio, parti precedenti rapidi","s":"Sì, dice che deve spingere!","sd":"Sente il bisogno di spingere","sev":{"optimal_s":240,"acceptable_s":480,"limit_s":900}},{"c":"Di continuo, una dietro l''altra!","cd":"Contrazioni continue","f":"Il secondo.","fd":"Secondo figlio","s":"Si vede la testa! Si vede la testa del bambino!","sd":"Parto in corso: si vede la testa","sev":{"optimal_s":120,"acceptable_s":300,"limit_s":600}}]}},"caller":{"gender":"m","phone_type":"any","panic_start":70,"ring_patience_s":35,"hold_patience_s":15,"reliability":0.95,"callback_chance":0.6},"opening":{"calm":"Pronto, mia moglie è incinta e le sono iniziate le contrazioni, credo che stia per partorire!","panic":"Pronto! Mia moglie sta partorendo! Cosa faccio?!"},"facts":{"indirizzo":{"display":"{location.street} {location.number}, {location.zone_name}"},"piano":{"display":"{location.floor_text}, campanello {caller_surname}"},"contrazioni":{"label":"Contrazioni","display":"{sc.cd}"},"figli":{"label":"Gravidanze precedenti","display":"{sc.fd}"},"spinta":{"label":"Fase del parto","display":"{sc.sd}"}},"nodes":[{"id":"q_dove","label":"Mi dica l''indirizzo: via e numero civico.","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":"{location.street} {location.number}.","panic":"{location.street}… il {location.number}!"},"error":{"threshold":65,"chance":0.4,"fact":"indirizzo","display":"{location.street} {location.number_wrong}, {location.zone_name}","reply":{"panic":"{location.street}… il {location.number_wrong}!"}}},{"id":"q_piano","label":"A che piano? Citofono?","cost_s":4,"reveals":["piano"],"reply":{"calm":"{location.floor_text}, {caller_surname}.","panic":"{location.floor_text}, {caller_surname}."},"requires":["q_dove"]},{"id":"q_contr","label":"Ogni quanto arrivano le contrazioni? Si sono rotte le acque?","cost_s":7,"reveals":["contrazioni"],"reply":{"calm":"{sc.c}","panic":"{sc.c}"}},{"id":"q_figli","label":"È il primo figlio?","cost_s":4,"reveals":["figli"],"reply":{"calm":"{sc.f}","panic":"{sc.f}"}},{"id":"q_spinta","label":"Sente il bisogno di spingere? Si vede già qualcosa?","cost_s":7,"reveals":["spinta"],"reply":{"calm":"{sc.s}","panic":"{sc.s}"},"requires":["q_contr"]},{"id":"a_rassicura","type":"reassure","label":"La faccia sdraiare sul fianco sinistro, prepari degli asciugamani puliti e apra la porta di casa.","cost_s":6,"panic_delta":-20,"reply":{"calm":"Ok… ok, asciugamani, porta aperta.","panic":"Sì! Asciugamani… va bene!"}}],"truth":{"event_type":"sanitaria.parto","agencies_required":["118"],"severity":"{sc.sev}","critical_facts":["indirizzo","contrazioni","spinta"],"hint_debrief":"Nel parto contano frequenza delle contrazioni, numero di gravidanze e bisogno di spingere: dicono quanto tempo resta."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('SAN_018', 'Convulsioni', 'sanitaria', 1, 3, 100, 1, 'mattina,pomeriggio,sera,notte', 0, 0, '{"code":"SAN_018","title":"Convulsioni","category":"sanitaria","phase":1,"difficulty":3,"weight":100,"min_rank":1,"time_bands":["mattina","pomeriggio","sera","notte"],"lang":"it","variables":{"location":{"pool":"stradario","zones":["centro","residenziale","colline"],"floor":[0,4]},"sc":{"choice":[{"open":"Pronto! Mia figlia di due anni ha avuto le convulsioni, tremava tutta! Ha la febbre alta.","d":"È durata un minuto, adesso ha smesso ma è molto addormentata.","dd":"Crisi di circa un minuto, finita; bambina assopita","t":"Ha la febbre a 39 e mezzo. Non ha battuto la testa.","td":"Febbre a 39,5, nessun trauma","sev":{"optimal_s":420,"acceptable_s":900,"limit_s":1800}},{"open":"Pronto, mio fratello è epilettico, ha una crisi e non smette!","d":"Sta andando avanti da sei, sette minuti… non si ferma!","dd":"Crisi in corso da oltre 6 minuti","t":"Niente febbre, è epilettico da anni, ma di solito dura poco.","td":"Epilessia nota, nessuna febbre","sev":{"optimal_s":180,"acceptable_s":420,"limit_s":900}},{"open":"Pronto, un ragazzo è caduto dalla bici qui davanti, ha sbattuto la testa e adesso sta tremando tutto!","d":"Ha tremato un minuto… adesso è fermo ma non risponde bene.","dd":"Convulsioni dopo trauma cranico, ora confuso","t":"Ha battuto la testa sull''asfalto, niente casco.","td":"Trauma cranico senza casco","sev":{"optimal_s":240,"acceptable_s":480,"limit_s":1200}}]}},"caller":{"gender":"any","phone_type":"any","panic_start":70,"ring_patience_s":35,"hold_patience_s":20,"reliability":0.95,"callback_chance":0.6},"opening":{"calm":"{sc.open}","panic":"{sc.open}"},"facts":{"indirizzo":{"display":"{location.street} {location.number}, {location.zone_name}"},"durata":{"label":"Crisi","display":"{sc.dd}"},"trauma":{"label":"Febbre o traumi","display":"{sc.td}"},"respiro":{"display":"Respira"}},"nodes":[{"id":"q_dove","label":"Mi dica l''indirizzo: via e numero civico.","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":"{location.street} {location.number}.","panic":"{location.street}… il {location.number}!"},"error":{"threshold":65,"chance":0.4,"fact":"indirizzo","display":"{location.street} {location.number_wrong}, {location.zone_name}","reply":{"panic":"{location.street}… il {location.number_wrong}!"}}},{"id":"q_durata","label":"Da quanto dura la crisi? Si è fermata?","cost_s":6,"reveals":["durata"],"reply":{"calm":"{sc.d}","panic":"{sc.d}"}},{"id":"q_trauma","label":"Ha febbre? Ha battuto la testa?","cost_s":6,"reveals":["trauma"],"reply":{"calm":"{sc.t}","panic":"{sc.t}"}},{"id":"q_respiro","label":"Adesso respira?","cost_s":5,"reveals":["respiro"],"reply":{"calm":"Sì, respira… un po'' rumoroso, ma respira.","panic":"Sì! Sì, respira!"},"requires":["q_durata"]},{"id":"a_rassicura","type":"reassure","label":"Non mettete niente in bocca, spostate gli oggetti intorno e quando smette mettetelo su un fianco.","cost_s":6,"panic_delta":-18,"reply":{"calm":"Va bene… grazie.","panic":"Sì… sì, va bene."}}],"truth":{"event_type":"sanitaria.convulsioni","acceptable_event_types":["sanitaria.malore","sanitaria.incosciente"],"agencies_required":["118"],"severity":"{sc.sev}","critical_facts":["indirizzo","durata"],"hint_debrief":"Una crisi che dura più di cinque minuti, o che segue un trauma alla testa, è un''emergenza grave: la durata va sempre chiesta."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('SAN_019', 'Persona a terra in strada', 'sanitaria', 1, 3, 100, 1, 'mattina,pomeriggio,sera,notte', 1, 0, '{"code":"SAN_019","title":"Persona a terra in strada","category":"sanitaria","phase":1,"difficulty":3,"weight":100,"min_rank":1,"time_bands":["mattina","pomeriggio","sera","notte"],"lang":"it","can_duplicate":true,"duplicates":{"chance":0.3,"max":1,"delay_s":[30,150],"near_twin_chance":0.12},"witness_opening":{"calm":"Buonasera, c''è una persona a terra in {location.street}, vicino a {location.landmark}.","panic":"C''è una persona a terra in {location.street}!"},"variables":{"location":{"pool":"stradario","zones":["centro","residenziale","industriale"],"floor":[0,0]},"sc":{"choice":[{"r":"No… non risponde. È un signore anziano.","rd":"Uomo anziano, non risponde","b":"Non vedo il petto muoversi… no, non respira!","bd":"Non respira","i":"Niente, ha la borsa della spesa rovesciata.","id2":"Nessun indizio particolare","event":"sanitaria.arresto_cardiaco","acc":["sanitaria.incosciente"],"sev":{"optimal_s":60,"acceptable_s":150,"limit_s":300}},{"r":"Borbotta qualcosa… puzza di alcol. È un ragazzo.","rd":"Ragazzo, risponde a monosillabi, odore di alcol","b":"Sì, respira, russa quasi.","bd":"Respira","i":"Ci sono delle bottiglie vuote vicino alla panchina.","id2":"Bottiglie vuote vicino","event":"sanitaria.intossicazione","acc":["sanitaria.malore","sanitaria.incosciente"],"sev":{"optimal_s":600,"acceptable_s":1200,"limit_s":2400}},{"r":"È una signora, risponde ma è confusa, tutta sudata.","rd":"Donna confusa e sudata","b":"Sì, respira normalmente.","bd":"Respira normalmente","i":"Ha un braccialetto… c''è scritto «diabetica».","id2":"Braccialetto: diabetica","event":"sanitaria.malore","acc":["sanitaria.incosciente"],"sev":{"optimal_s":300,"acceptable_s":600,"limit_s":1500}}]}},"caller":{"gender":"m","phone_type":"mobile","panic_start":45,"ring_patience_s":35,"hold_patience_s":30,"reliability":0.95,"callback_chance":0.4},"opening":{"calm":"Pronto, c''è una persona a terra sul marciapiede, non so cosa abbia.","panic":"Pronto! C''è uno a terra per strada, non si muove!"},"facts":{"indirizzo":{"display":"{location.street}, vicino a {location.landmark} ({location.zone_name})"},"coscienza":{"display":"{sc.rd}"},"respiro":{"display":"{sc.bd}"},"indizi":{"label":"Indizi","display":"{sc.id2}"}},"nodes":[{"id":"q_dove","label":"Dove si trova esattamente? Via e un punto di riferimento.","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":"In {location.street}, vicino a {location.landmark}.","panic":"{location.street}! Davanti a {location.landmark}!"},"error":{"threshold":65,"chance":0.4,"fact":"indirizzo","display":"{location.street_wrong} (incerto)","reply":{"panic":"In {location.street_wrong}… credo, non ne sono sicuro!"}}},{"id":"q_risponde","label":"Si avvicini e gli parli forte, gli tocchi la spalla: risponde?","cost_s":9,"reveals":["coscienza"],"reply":{"calm":"{sc.r}","panic":"{sc.r}"}},{"id":"q_respiro","label":"Guardi il petto per qualche secondo: respira normalmente?","cost_s":9,"reveals":["respiro"],"reply":{"calm":"{sc.b}","panic":"{sc.b}"},"requires":["q_risponde"]},{"id":"q_indizi","label":"Vede qualcosa intorno o addosso a lui: bottiglie, sangue, un bracciale medico?","cost_s":6,"reveals":["indizi"],"reply":{"calm":"{sc.i}","panic":"{sc.i}"}},{"id":"a_rassicura","type":"reassure","label":"Resti con la persona e chieda aiuto a chi passa: l''ambulanza è in arrivo.","cost_s":6,"panic_delta":-12,"reply":{"calm":"Va bene… grazie.","panic":"Sì… sì, va bene."}}],"truth":{"event_type":"{sc.event}","acceptable_event_types":"{sc.acc}","agencies_required":["118"],"severity":"{sc.sev}","critical_facts":["indirizzo","coscienza","respiro"],"hint_debrief":"Davanti a una persona a terra servono tre cose: dove, se risponde, se respira. Gli indizi intorno aiutano a capire cosa è successo."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('SAN_020', 'Tutta la famiglia ha mal di testa', 'sanitaria', 1, 5, 100, 1, 'mattina,pomeriggio,sera,notte', 0, 0, '{"code":"SAN_020","title":"Tutta la famiglia ha mal di testa","category":"sanitaria","phase":1,"difficulty":5,"weight":100,"min_rank":1,"time_bands":["mattina","pomeriggio","sera","notte"],"lang":"it","variables":{"location":{"pool":"stradario","zones":["centro","residenziale","colline"],"floor":[0,3]},"sc":{"choice":[{"f":"Abbiamo la stufa a pellet accesa in soggiorno da stamattina, con le finestre chiuse per il freddo.","fd":"Stufa a pellet accesa, finestre chiuse"},{"f":"C''è la caldaia vecchia in bagno… ieri l''ho sentita fare un rumore strano.","fd":"Vecchia caldaia in bagno, rumori anomali"},{"f":"Ho acceso un braciere in camera per scaldare… fa così freddo.","fd":"Braciere acceso in camera da letto"}]}},"caller":{"gender":"f","phone_type":"any","panic_start":30,"ring_patience_s":35,"hold_patience_s":30,"reliability":0.9,"callback_chance":0.4},"opening":{"calm":"Buonasera, scusi… a casa abbiamo tutti mal di testa e nausea, anche i bambini. Sarà un virus? Il piccolo non si sveglia bene.","panic":"Pronto… stiamo tutti male, mal di testa, nausea… il piccolo non si sveglia bene!"},"facts":{"indirizzo":{"display":"{location.street} {location.number}, {location.zone_name}"},"piano":{"display":"{location.floor_text}, campanello {caller_surname}"},"sintomi":{"label":"Sintomi","display":"Tutta la famiglia: mal di testa e nausea; il bambino più piccolo fatica a svegliarsi"},"fonte":{"label":"Possibile fonte","display":"{sc.fd}"},"persone":{"display":"Quattro persone in casa, due bambini"}},"nodes":[{"id":"q_dove","label":"Mi dica l''indirizzo: via e numero civico.","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":"{location.street} {location.number}.","panic":"{location.street}… il {location.number}!"},"error":{"threshold":65,"chance":0.4,"fact":"indirizzo","display":"{location.street} {location.number_wrong}, {location.zone_name}","reply":{"panic":"{location.street}… il {location.number_wrong}!"}}},{"id":"q_piano","label":"A che piano abitate?","cost_s":4,"reveals":["piano"],"reply":{"calm":"Al {location.floor_text}, {caller_surname}.","panic":"Al {location.floor_text}, {caller_surname}."},"requires":["q_dove"]},{"id":"q_sintomi","label":"Da quando state male? Chi è più grave?","cost_s":7,"reveals":["sintomi"],"reply":{"calm":"Da un paio d''ore. Il più piccolo dorme e se lo chiamo apre appena gli occhi.","panic":"Da un paio d''ore. Il più piccolo dorme e se lo chiamo apre appena gli occhi."}},{"id":"q_fonte","label":"Avete stufe, caldaie o bracieri accesi in casa?","cost_s":6,"reveals":["fonte"],"reply":{"calm":"{sc.f}","panic":"{sc.f}"}},{"id":"q_persone","label":"Quante persone ci sono in casa?","cost_s":4,"reveals":["persone"],"reply":{"calm":"Siamo in quattro, io, mio marito e i due bambini.","panic":"Siamo in quattro, io, mio marito e i due bambini."}},{"id":"a_esci","type":"reassure","label":"Aprite subito tutte le finestre, spegnete la stufa se potete e uscite tutti all''aria aperta, portando fuori il piccolo.","cost_s":6,"panic_delta":-10,"reply":{"calm":"Oddio… sì, usciamo subito.","panic":"Usciamo! Usciamo subito!"}}],"truth":{"event_type":"sanitaria.intossicazione","agencies_required":["118","115"],"severity":{"optimal_s":240,"acceptable_s":480,"limit_s":1200},"critical_facts":["indirizzo","fonte"],"hint_debrief":"Tutti in casa con mal di testa e nausea, e una fonte di combustione accesa: è monossido di carbonio, non un virus. Servono 118 e Vigili del fuoco, e bisogna far uscire tutti."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('SAN_021', 'Ha preso qualcosa che non doveva', 'sanitaria', 1, 4, 100, 1, 'mattina,pomeriggio,sera,notte', 0, 0, '{"code":"SAN_021","title":"Ha preso qualcosa che non doveva","category":"sanitaria","phase":1,"difficulty":4,"weight":100,"min_rank":1,"time_bands":["mattina","pomeriggio","sera","notte"],"lang":"it","variables":{"location":{"pool":"stradario","zones":["centro","residenziale","colline"],"floor":[0,4]},"sc":{"choice":[{"open":"Pronto! Mio figlio di tre anni ha bevuto il detersivo della lavastoviglie!","c":"Ne ha bevuto un sorso, forse due… cinque minuti fa.","cd":"Detersivo per lavastoviglie, un sorso o due, 5 minuti fa","k":"Piange, sta bene, ma ha la bocca arrossata.","kd":"Sveglio, piange, bocca arrossata","n":"Sì, ce l''ho qui: detersivo gel per lavastoviglie.","nd":"Detersivo gel per lavastoviglie"},{"open":"Pronto, mia madre ha preso le pastiglie due volte stamattina, credo… non si ricorda.","c":"Le pastiglie della pressione e quelle per il sangue, due volte.","cd":"Doppia dose di antipertensivi e anticoagulante","k":"È un po'' confusa e dice che le gira la testa.","kd":"Confusa, capogiri","n":"Sì, ecco… sono il Coumadin e un''altra che non so leggere.","nd":"Anticoagulante e un antipertensivo"},{"open":"Pronto, siamo a una festa… un mio amico ha bevuto e preso delle pastiglie, adesso non sta in piedi.","c":"Non lo so quante… un paio, un''ora fa, con la vodka.","cd":"Pastiglie sconosciute con alcol, un''ora fa","k":"Dorme, se lo scuoti apre gli occhi e poi li richiude.","kd":"Soporoso, risponde appena","n":"No… non c''è nessuna scatola.","nd":"Sostanza sconosciuta"}]}},"caller":{"gender":"any","phone_type":"any","panic_start":60,"ring_patience_s":35,"hold_patience_s":20,"reliability":0.95,"callback_chance":0.6},"opening":{"calm":"{sc.open}","panic":"{sc.open}"},"facts":{"indirizzo":{"display":"{location.street} {location.number}, {location.zone_name}"},"cosa":{"label":"Cosa e quando","display":"{sc.cd}"},"coscienza":{"display":"{sc.kd}"},"sostanza":{"label":"Confezione","display":"{sc.nd}"}},"nodes":[{"id":"q_dove","label":"Mi dica l''indirizzo: via e numero civico.","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":"{location.street} {location.number}.","panic":"{location.street}… il {location.number}!"},"error":{"threshold":65,"chance":0.4,"fact":"indirizzo","display":"{location.street} {location.number_wrong}, {location.zone_name}","reply":{"panic":"{location.street}… il {location.number_wrong}!"}}},{"id":"q_cosa","label":"Cosa ha preso, quanto e quando?","cost_s":7,"reveals":["cosa"],"reply":{"calm":"{sc.c}","panic":"{sc.c}"}},{"id":"q_coscienza","label":"Come sta adesso? È sveglio, risponde?","cost_s":6,"reveals":["coscienza"],"reply":{"calm":"{sc.k}","panic":"{sc.k}"}},{"id":"q_confezione","label":"Ha la confezione? Mi legge il nome?","cost_s":7,"reveals":["sostanza"],"reply":{"calm":"{sc.n}","panic":"{sc.n}"}},{"id":"a_rassicura","type":"reassure","label":"Non lo faccia vomitare, non gli dia da bere, e tenga la confezione per i soccorritori.","cost_s":6,"panic_delta":-15,"reply":{"calm":"Va bene… grazie.","panic":"Sì… sì, va bene."}}],"truth":{"event_type":"sanitaria.intossicazione","agencies_required":["118"],"severity":{"optimal_s":300,"acceptable_s":600,"limit_s":1500},"critical_facts":["indirizzo","cosa"],"hint_debrief":"Nelle intossicazioni servono cosa, quanto e quando: la confezione vale più di mille descrizioni. Non va mai indotto il vomito."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('SAN_022', 'Infortunio in azienda', 'sanitaria', 1, 4, 100, 1, 'mattina,pomeriggio,sera,notte', 0, 0, '{"code":"SAN_022","title":"Infortunio in azienda","category":"sanitaria","phase":1,"difficulty":4,"weight":100,"min_rank":1,"time_bands":["mattina","pomeriggio","sera","notte"],"lang":"it","variables":{"location":{"pool":"stradario","zones":["industriale"],"floor":[0,0]},"sc":{"choice":[{"h":"È caduto da una scala, saranno tre metri.","hd":"Caduta da circa 3 metri","k":"È sveglio, si lamenta per la gamba, dice che non la sente bene.","kd":"Cosciente, dolore alla gamba","x":"No, è a terra libero.","xd":"Nessuna parte incastrata","ag":["118"],"event":"sanitaria.trauma_caduta"},{"h":"È caduto dal tetto del capannone… sei metri almeno!","hd":"Caduta da almeno 6 metri","k":"Non risponde! Respira ma non risponde!","kd":"Non risponde, respira","x":"No, è sul piazzale.","xd":"Nessuna parte incastrata","ag":["118"],"event":"sanitaria.trauma_caduta"},{"h":"Nessuna caduta: gli è rimasta la mano nella pressa!","hd":"Mano schiacciata in una pressa","k":"È sveglio, urla dal dolore, è bianchissimo.","kd":"Cosciente, pallido, dolore forte","x":"Sì! La mano è ancora dentro, la macchina è ferma ma non riusciamo a tirarla fuori!","xd":"Mano incastrata nella macchina","ag":["118","115"],"event":"sanitaria.ferita"}]}},"caller":{"gender":"m","phone_type":"mobile","panic_start":60,"ring_patience_s":30,"hold_patience_s":30,"reliability":0.95,"callback_chance":0.6},"opening":{"calm":"Pronto, qui in ditta un operaio si è fatto male, serve un''ambulanza!","panic":"Pronto! Un incidente in ditta, un operaio si è fatto male, presto!"},"facts":{"indirizzo":{"display":"{location.street} {location.number}, zona artigianale"},"dinamica":{"label":"Dinamica","display":"{sc.hd}"},"coscienza":{"display":"{sc.kd}"},"incastro":{"label":"Incastrato","display":"{sc.xd}"}},"nodes":[{"id":"q_dove","label":"In che via è l''azienda? Numero civico e da che ingresso si entra?","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":"{location.street} {location.number}, entrate dal cancello grande.","panic":"{location.street}… il {location.number}!"},"error":{"threshold":65,"chance":0.4,"fact":"indirizzo","display":"{location.street} {location.number_wrong}, {location.zone_name}","reply":{"panic":"{location.street}… il {location.number_wrong}!"}}},{"id":"q_come","label":"Cosa è successo esattamente?","cost_s":6,"reveals":["dinamica"],"reply":{"calm":"{sc.h}","panic":"{sc.h}"}},{"id":"q_coscienza","label":"È sveglio? Le risponde?","cost_s":5,"reveals":["coscienza"],"reply":{"calm":"{sc.k}","panic":"{sc.k}"}},{"id":"q_incastro","label":"È rimasto incastrato da qualche parte?","cost_s":5,"reveals":["incastro"],"reply":{"calm":"{sc.x}","panic":"{sc.x}"}},{"id":"a_rassicura","type":"reassure","label":"Non spostatelo, spegnete i macchinari e mandate qualcuno al cancello ad aspettare i soccorsi.","cost_s":6,"panic_delta":-15,"reply":{"calm":"Va bene… grazie.","panic":"Sì… sì, va bene."}}],"truth":{"event_type":"{sc.event}","acceptable_event_types":["sanitaria.trauma_caduta","sanitaria.ferita"],"agencies_required":"{sc.ag}","agencies_acceptable":["CC"],"severity":{"optimal_s":300,"acceptable_s":600,"limit_s":1200},"critical_facts":["indirizzo","coscienza","incastro"],"hint_debrief":"Negli infortuni sul lavoro va chiesto se la persona è incastrata: in quel caso servono anche i Vigili del fuoco."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('SAN_023', 'Ferita che sanguina', 'sanitaria', 1, 3, 100, 1, 'mattina,pomeriggio,sera,notte', 0, 0, '{"code":"SAN_023","title":"Ferita che sanguina","category":"sanitaria","phase":1,"difficulty":3,"weight":100,"min_rank":1,"time_bands":["mattina","pomeriggio","sera","notte"],"lang":"it","variables":{"location":{"pool":"stradario","zones":["centro","residenziale","colline"],"floor":[0,4]},"sc":{"choice":[{"open":"Pronto, mi sono tagliato con il coltello mentre cucinavo, non smette di sanguinare!","f":"Sul palmo della mano, è profondo.","fd":"Taglio profondo al palmo della mano","s":"Cola tanto, ho già inzuppato due strofinacci.","sd":"Sanguinamento continuo","c":"Stavo tagliando il pane, mi è scivolato.","cd":"Incidente domestico in cucina","event":"sanitaria.ferita","ag":["118"],"acc":[]},{"open":"Pronto! Mio figlio è caduto contro la portafinestra, il vetro si è rotto, ha un taglio alla gamba!","f":"Sulla coscia, lungo così.","fd":"Taglio lungo sulla coscia","s":"Esce a fiotti! A fiotti!","sd":"Sangue a fiotti","c":"Correva in casa ed è finito contro il vetro.","cd":"Caduta contro un vetro","event":"sanitaria.ferita","ag":["118"],"acc":[]},{"open":"Pronto, mio fratello è ferito, gli hanno dato una coltellata!","f":"Al fianco, qui sotto le costole.","fd":"Ferita al fianco","s":"Esce tanto sangue, sta diventando bianco.","sd":"Sanguinamento abbondante, pallore","c":"Un tizio lo ha aggredito sotto casa ed è scappato verso la piazza.","cd":"Aggressione con coltello, l''aggressore è fuggito","event":"sicurezza.aggressione","ag":["118","{location.police}"],"acc":["sanitaria.ferita"]}],"weights":[40,35,25]}},"caller":{"gender":"any","phone_type":"any","panic_start":65,"ring_patience_s":35,"hold_patience_s":20,"reliability":0.95,"callback_chance":0.6},"opening":{"calm":"{sc.open}","panic":"{sc.open}"},"facts":{"indirizzo":{"display":"{location.street} {location.number}, {location.zone_name}"},"ferita":{"label":"Ferita","display":"{sc.fd}"},"sangue":{"label":"Sanguinamento","display":"{sc.sd}"},"dinamica":{"label":"Dinamica","display":"{sc.cd}"}},"nodes":[{"id":"q_dove","label":"Mi dica l''indirizzo: via e numero civico.","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":"{location.street} {location.number}.","panic":"{location.street}… il {location.number}!"},"error":{"threshold":65,"chance":0.4,"fact":"indirizzo","display":"{location.street} {location.number_wrong}, {location.zone_name}","reply":{"panic":"{location.street}… il {location.number_wrong}!"}}},{"id":"q_ferita","label":"Dov''è la ferita? Quanto è grande?","cost_s":5,"reveals":["ferita"],"reply":{"calm":"{sc.f}","panic":"{sc.f}"}},{"id":"q_sangue","label":"Il sangue esce a fiotti o cola? Riuscite a premere?","cost_s":6,"reveals":["sangue"],"reply":{"calm":"{sc.s}","panic":"{sc.s}"}},{"id":"q_come","label":"Com''è successo?","cost_s":6,"reveals":["dinamica"],"reply":{"calm":"{sc.c}","panic":"{sc.c}"}},{"id":"a_premi","type":"reassure","label":"Prema forte sulla ferita con un panno pulito e non lo tolga, anche se si inzuppa: ne aggiunga un altro sopra.","cost_s":6,"panic_delta":-18,"reply":{"calm":"Ok, premo forte.","panic":"Premo! Sto premendo!"}}],"truth":{"event_type":"{sc.event}","acceptable_event_types":"{sc.acc}","agencies_required":"{sc.ag}","severity":{"optimal_s":240,"acceptable_s":480,"limit_s":1200},"critical_facts":["indirizzo","sangue","dinamica"],"hint_debrief":"Chiedere come è successo non è curiosità: una ferita da aggressione richiede anche le forze dell''ordine."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('SAN_024', 'Punto da un insetto, o da una vipera', 'sanitaria', 1, 3, 100, 1, 'mattina,pomeriggio,sera,notte', 0, 0, '{"code":"SAN_024","title":"Punto da un insetto, o da una vipera","category":"sanitaria","phase":1,"difficulty":3,"weight":100,"min_rank":1,"time_bands":["mattina","pomeriggio","sera","notte"],"lang":"it","variables":{"location":{"pool":"stradario","zones":["colline","montagna"],"floor":[0,0]},"sc":{"choice":[{"open":"Buongiorno, mi ha punto un calabrone sul braccio, è gonfio, volevo sapere cosa fare.","s":"Solo il braccio gonfio e rosso, per il resto sto bene.","sd":"Gonfiore locale al braccio, nessun altro sintomo","a":"Non che io sappia.","ad":"Nessuna allergia nota","event":"sanitaria.reazione_allergica","sev":{"optimal_s":900,"acceptable_s":1800,"limit_s":3600}},{"open":"Pronto! Mio marito è allergico alle api, l''hanno punto e adesso fa fatica a respirare!","s":"Ha la faccia gonfia, gli si chiude la gola, è pieno di bolle!","sd":"Viso gonfio, gola che si chiude, orticaria","a":"Sì, è allergico, ha la siringa di adrenalina ma l''ha lasciata a casa!","ad":"Allergia nota, adrenalina non disponibile","event":"sanitaria.reazione_allergica","sev":{"optimal_s":120,"acceptable_s":300,"limit_s":600}},{"open":"Pronto, sono sul sentiero, mi ha morso un serpente alla caviglia, credo una vipera!","s":"La caviglia si sta gonfiando e diventa scura, mi gira un po'' la testa.","sd":"Caviglia gonfia e scura, capogiri","a":"No, niente allergie.","ad":"Nessuna allergia","event":"sanitaria.soccorso_impervio","sev":{"optimal_s":600,"acceptable_s":1200,"limit_s":2400}}]}},"caller":{"gender":"any","phone_type":"mobile","panic_start":45,"ring_patience_s":35,"hold_patience_s":30,"reliability":0.95,"callback_chance":0.6},"opening":{"calm":"{sc.open}","panic":"{sc.open}"},"facts":{"indirizzo":{"display":"{location.street}, vicino a {location.landmark} ({location.zone_name})"},"sintomi":{"label":"Sintomi","display":"{sc.sd}"},"allergie":{"label":"Allergie","display":"{sc.ad}"}},"nodes":[{"id":"q_dove","label":"Dove vi trovate? Via, località o un punto di riferimento.","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":"In {location.street}, vicino a {location.landmark}.","panic":"{location.street}! Vicino a {location.landmark}!"},"error":{"threshold":65,"chance":0.4,"fact":"indirizzo","display":"{location.street_wrong} (incerto)","reply":{"panic":"In {location.street_wrong}… credo, non ne sono sicuro!"}}},{"id":"q_sintomi","label":"Che sintomi ci sono oltre al gonfiore? Respira bene?","cost_s":7,"reveals":["sintomi"],"reply":{"calm":"{sc.s}","panic":"{sc.s}"}},{"id":"q_allergie","label":"È allergico a qualcosa? Ha farmaci con sé?","cost_s":5,"reveals":["allergie"],"reply":{"calm":"{sc.a}","panic":"{sc.a}"}},{"id":"a_rassicura","type":"reassure","label":"Resti fermo e tranquillo, tolga anelli e orologi dalla parte colpita e non la stringa con lacci.","cost_s":6,"panic_delta":-15,"reply":{"calm":"Va bene… grazie.","panic":"Sì… sì, va bene."}}],"truth":{"event_type":"{sc.event}","acceptable_event_types":["sanitaria.reazione_allergica","sanitaria.difficolta_respiratoria","sanitaria.soccorso_impervio"],"agencies_required":["118"],"severity":"{sc.sev}","critical_facts":["indirizzo","sintomi"],"hint_debrief":"Una puntura diventa urgente quando compaiono sintomi lontani dal punto colpito: gonfiore del viso, respiro difficile, capogiri."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('SAN_025', 'Mi sento morire', 'sanitaria', 1, 5, 100, 1, 'mattina,pomeriggio,sera,notte', 0, 0, '{"code":"SAN_025","title":"Mi sento morire","category":"sanitaria","phase":1,"difficulty":5,"weight":100,"min_rank":1,"time_bands":["mattina","pomeriggio","sera","notte"],"lang":"it","variables":{"location":{"pool":"stradario","zones":["centro","residenziale","colline"],"floor":[0,4]},"sc":{"choice":[{"s":"Mi formicolano le mani, il cuore batte fortissimo, ho paura di morire… mi è già successo l''anno scorso.","sd":"Formicolio alle mani, batticuore, paura di morire; episodio simile l''anno scorso","r":"Prendo solo la pillola… e sono molto stressata con il lavoro.","rd":"Nessuna malattia nota, forte stress","event":"sanitaria.malore","acc":["sanitaria.difficolta_respiratoria"]},{"s":"Ho un dolore al petto quando respiro e mi manca il fiato… sono appena tornata da un volo di dodici ore.","sd":"Dolore toracico quando respira, fiato corto, dopo un volo di 12 ore","r":"Prendo la pillola… e ho un polpaccio gonfio da ieri, pensavo fosse il viaggio.","rd":"Pillola anticoncezionale, polpaccio gonfio","event":"sanitaria.dolore_toracico","acc":["sanitaria.difficolta_respiratoria"]}],"weights":[60,40]}},"caller":{"gender":"f","phone_type":"any","panic_start":88,"ring_patience_s":35,"hold_patience_s":20,"reliability":0.7,"callback_chance":0.6},"opening":{"calm":"Pronto… non respiro bene, mi sento morire…","panic":"Pronto?! Aiutatemi, non respiro, mi sento morire!"},"facts":{"indirizzo":{"display":"{location.street} {location.number}, {location.zone_name}"},"piano":{"display":"{location.floor_text}, campanello {caller_surname}"},"sintomi":{"label":"Sintomi","display":"{sc.sd}"},"rischi":{"label":"Terapie e precedenti","display":"{sc.rd}"}},"nodes":[{"id":"q_dove","label":"Mi dica l''indirizzo: via e numero civico.","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":"{location.street} {location.number}.","panic":"{location.street}… il {location.number}!"},"error":{"threshold":60,"chance":0.5,"fact":"indirizzo","display":"{location.street} {location.number_wrong}, {location.zone_name}","reply":{"panic":"{location.street}… il {location.number_wrong}!"}}},{"id":"q_piano","label":"Che piano? Può aprire la porta?","cost_s":4,"reveals":["piano"],"reply":{"calm":"Al {location.floor_text}… sì, apro.","panic":"Al {location.floor_text}… sì, apro."},"requires":["q_dove"]},{"id":"q_sintomi","label":"Mi descriva cosa sente, con calma.","cost_s":8,"reveals":["sintomi"],"reply":{"calm":"{sc.s}","panic":"Non lo so! Il petto… le mani… non respiro!"},"error":{"threshold":75,"chance":0.8,"fact":"sintomi","display":"Racconto confuso: «il petto, le mani, non respiro»","reply":{"panic":"Non lo so! Il petto… le mani… non respiro!"}}},{"id":"q_rischi","label":"Prende farmaci? Le è già successo? Ha fatto viaggi di recente?","cost_s":7,"reveals":["rischi"],"reply":{"calm":"{sc.r}","panic":"{sc.r}"}},{"id":"a_rassicura","type":"reassure","label":"Sono qui con lei. Respiri piano insieme a me: dentro dal naso… fuori dalla bocca.","cost_s":10,"panic_delta":-30,"reply":{"calm":"Ok… dentro… fuori… va un po'' meglio.","panic":"Ok… ci provo… dentro… fuori…"}}],"truth":{"event_type":"{sc.event}","acceptable_event_types":"{sc.acc}","agencies_required":["118"],"severity":{"optimal_s":300,"acceptable_s":600,"limit_s":1500},"critical_facts":["indirizzo","sintomi"],"hint_debrief":"Chi è nel panico racconta male: prima si calma, poi si chiede. Un «attacco di panico» dopo un lungo volo, con un polpaccio gonfio, può essere un''embolia."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('SAN_054', 'Anziana con febbre e confusa', 'sanitaria', 1, 2, 100, 1, 'mattina,pomeriggio,sera,notte', 0, 0, '{"code":"SAN_054","title":"Anziana con febbre e confusa","category":"sanitaria","phase":1,"difficulty":2,"weight":100,"min_rank":1,"time_bands":["mattina","pomeriggio","sera","notte"],"lang":"it","variables":{"location":{"pool":"stradario","zones":["centro","residenziale","colline"],"floor":[0,4]},"sc":{"choice":[{"s":"Ha la febbre a 38 da due giorni, oggi è un po'' più stanca ma mangia e parla normalmente.","sd":"Febbre da due giorni, stanca ma lucida","event":"sanitaria.malore","sev":{"optimal_s":1200,"acceptable_s":2400,"limit_s":4800}},{"s":"Ha 39 e mezzo, stamattina non mi riconosceva e respira veloce, non ha fatto pipì da ieri.","sd":"Febbre alta, confusa, respiro rapido, non urina da ieri","event":"sanitaria.malore","sev":{"optimal_s":420,"acceptable_s":900,"limit_s":1800}}],"weights":[50,50]}},"caller":{"gender":"f","phone_type":"any","panic_start":35,"ring_patience_s":35,"hold_patience_s":30,"reliability":0.95,"callback_chance":0.6},"opening":{"calm":"Buonasera, mia madre ha la febbre alta e non so se portarla in ospedale.","panic":"Pronto, mia madre sta male, ha la febbre altissima!"},"facts":{"indirizzo":{"display":"{location.street} {location.number}, {location.zone_name}"},"piano":{"display":"{location.floor_text}, campanello {caller_surname}"},"sintomi":{"label":"Sintomi","display":"{sc.sd}"}},"nodes":[{"id":"q_dove","label":"Mi dica l''indirizzo: via e numero civico.","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":"{location.street} {location.number}.","panic":"{location.street}… il {location.number}!"},"error":{"threshold":65,"chance":0.4,"fact":"indirizzo","display":"{location.street} {location.number_wrong}, {location.zone_name}","reply":{"panic":"{location.street}… il {location.number_wrong}!"}}},{"id":"q_piano","label":"A che piano?","cost_s":4,"reveals":["piano"],"reply":{"calm":"Al {location.floor_text}, {caller_surname}.","panic":"Al {location.floor_text}, {caller_surname}."},"requires":["q_dove"]},{"id":"q_sintomi","label":"Da quanto ha la febbre? È lucida, respira bene?","cost_s":8,"reveals":["sintomi"],"reply":{"calm":"{sc.s}","panic":"{sc.s}"}},{"id":"a_rassicura","type":"reassure","label":"La tenga al fresco e le dia da bere a piccoli sorsi, se riesce.","cost_s":6,"panic_delta":-10,"reply":{"calm":"Va bene… grazie.","panic":"Sì… sì, va bene."}}],"truth":{"event_type":"{sc.event}","acceptable_event_types":["sanitaria.difficolta_respiratoria"],"agencies_required":["118"],"severity":"{sc.sev}","critical_facts":["indirizzo","sintomi"],"hint_debrief":"La febbre da sola raramente è urgente; confusione, respiro rapido e niente urina in un anziano indicano un''infezione grave."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('SIC_006', 'Ladri in casa', 'sicurezza', 1, 3, 90, 1, 'mattina,sera,notte', 0, 0, '{"code":"SIC_006","title":"Ladri in casa","category":"sicurezza","phase":1,"difficulty":3,"weight":90,"min_rank":1,"time_bands":["mattina","sera","notte"],"lang":"it","variables":{"location":{"pool":"stradario","zones":["residenziale","colline"],"floor":[0,2]},"intruders":{"choice":[{"text":"(sussurra) Almeno due… li sento parlare. Non so se sono armati.","display":"Almeno due persone, armi non viste"},{"text":"(sussurra) Uno solo, credo… ha rotto il vetro della portafinestra.","display":"Una persona, entrata rompendo la portafinestra"}]},"car":{"choice":[{"text":"(sussurra, agitata) C''è una macchina scura col motore acceso davanti al cancello… non vedo la targa.","display":"Auto scura col motore acceso davanti al cancello"},{"text":"(sussurra) Non vedo niente… è tutto buio fuori.","display":"Nessun veicolo visibile"}]}},"caller":{"gender":"f","phone_type":"mobile","panic_start":60,"ring_patience_s":30,"hold_patience_s":15,"reliability":0.9,"callback_chance":0.9},"opening":{"calm":"(sussurra) Pronto… ci sono dei ladri in casa. Li sento al piano di sotto.","panic":"(sussurra, con il fiato corto) Pronto… sono in casa… sono in casa, li sento!"},"facts":{"indirizzo":{"display":"{location.street} {location.number}, {location.zone_name}"},"posizione":{"label":"Dove si trova la chiamante","display":"Chiusa a chiave in camera da letto, al piano di sopra"},"sospetti":{"display":"{intruders.display}"},"veicoli":{"display":"{car.display}"}},"nodes":[{"id":"q_dove","label":"Mi dica l''indirizzo: via e numero civico.","cost_s":7,"reveals":["indirizzo"],"reply":{"calm":"(sussurra) {location.street} {location.number}.","panic":"(sussurra) {location.street}… {location.number}…"},"error":{"threshold":70,"chance":0.45,"fact":"indirizzo","display":"{location.street} {location.number_wrong}, {location.zone_name}","reply":{"panic":"(sussurra) {location.street}… {location.number_wrong}…"}}},{"id":"q_posizione","label":"Lei dove si trova adesso? È al sicuro?","cost_s":6,"reveals":["posizione"],"reply":{"calm":"(sussurra) In camera, al piano di sopra. Ho chiuso la porta a chiave.","panic":"(sussurra) In camera… ho chiuso a chiave… ho paura."}},{"id":"q_quanti","label":"Quante persone sente? Ha visto armi?","cost_s":6,"reveals":["sospetti"],"reply":{"calm":"{intruders.text}","panic":"{intruders.text}"}},{"id":"q_auto","label":"Riesce a guardare dalla finestra senza farsi vedere? C''è un''auto fuori?","cost_s":12,"panic_delta":15,"reveals":["veicoli"],"reply":{"calm":"{car.text}","panic":"{car.text}"}},{"id":"a_silenzio","type":"reassure","label":"Resti dov''è, in silenzio, e non apra a nessuno. Io resto in linea con lei.","cost_s":6,"panic_delta":-18,"reply":{"calm":"(sussurra) Va bene… resto qui.","panic":"(sussurra) Sì… sì… non se ne vada, la prego."}}],"truth":{"event_type":"sicurezza.furto_in_corso","agencies_required":["{location.police}"],"severity":{"optimal_s":180,"acceptable_s":420,"limit_s":900},"critical_facts":["indirizzo","sospetti"],"hint_debrief":"Chi sussurra non può reggere lunghe attese: metterla in attesa o chiederle di muoversi aumenta il rischio. Competenza PS o CC secondo la zona."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('SIC_011', 'Lite violenta sentita dal vicino', 'sicurezza', 1, 5, 80, 1, 'sera,notte,pomeriggio', 0, 0, '{"code":"SIC_011","title":"Lite violenta sentita dal vicino","category":"sicurezza","phase":1,"difficulty":5,"weight":80,"min_rank":1,"time_bands":["sera","notte","pomeriggio"],"lang":"it","variables":{"location":{"pool":"stradario","zones":["centro","residenziale","colline"],"floor":[1,4]},"fight":{"choice":[{"text":"Un uomo che grida, una donna che piange… e prima dei colpi, come mobili che cadono.","display":"Uomo che urla, donna che piange, rumori di colpi","agencies":["{location.police}"],"event":"sicurezza.violenza_domestica"},{"text":"Adesso ho sentito lei gridare «basta, mi fai male»… e poi più niente. Silenzio.","display":"Una donna ha gridato «mi fai male», poi silenzio","agencies":["{location.police}","118"],"event":"sicurezza.violenza_domestica"}]},"weapons":{"choice":[{"text":"Non lo so… lui va a caccia, ha dei fucili, me l''aveva detto.","display":"Possibili fucili da caccia in casa"},{"text":"No, non credo.","display":"Nessuna arma nota"}],"weights":[35,65]}},"caller":{"gender":"m","phone_type":"any","panic_start":35,"ring_patience_s":45,"hold_patience_s":45,"reliability":0.95,"callback_chance":0.6},"opening":{"calm":"Buonasera, non so se faccio bene a chiamare… dall''appartamento accanto sento urlare da mezz''ora.","panic":"Pronto, scusate… qui di fianco stanno urlando, sento dei colpi, non so cosa fare."},"facts":{"indirizzo":{"display":"{location.street} {location.number}, {location.floor_text}: appartamento accanto al chiamante"},"evento":{"display":"{fight.display}"},"persone":{"display":"Coppia con una bambina piccola, probabilmente in casa"},"pericoli":{"display":"{weapons.display}"},"reazione":{"label":"Tentativo del chiamante","display":"Il chiamante ha bussato: l''uomo ha reagito con rabbia"}},"nodes":[{"id":"q_dove","label":"Mi dica l''indirizzo e il piano.","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":"{location.street} {location.number}, al {location.floor_text}. È l''appartamento di fianco al mio.","panic":"{location.street} {location.number}, {location.floor_text}."}},{"id":"q_cosa","label":"Cosa sente esattamente?","cost_s":7,"reveals":["evento"],"reply":{"calm":"{fight.text}","panic":"{fight.text}"}},{"id":"q_bambini","label":"Sa chi vive in quell''appartamento? Ci sono bambini?","cost_s":6,"reveals":["persone"],"reply":{"calm":"Una coppia, hanno una bambina piccola. Credo sia in casa.","panic":"Una coppia… con una bambina!"}},{"id":"q_armi","label":"Sa se in casa ci sono armi?","cost_s":5,"reveals":["pericoli"],"reply":{"calm":"{weapons.text}","panic":"{weapons.text}"}},{"id":"q_bussa","label":"Provi a bussare e a chiedere se va tutto bene.","cost_s":20,"panic_delta":25,"reveals":["reazione"],"reply":{"calm":"Ho bussato… hanno smesso, poi lui ha urlato di farmi gli affari miei. Ho paura adesso.","panic":"Ho bussato… lui mi ha urlato contro! Ho paura!"}},{"id":"a_resta","type":"reassure","label":"Resti in casa sua, chiuda la porta e non intervenga. Arrivano le forze dell''ordine.","cost_s":6,"panic_delta":-15,"reply":{"calm":"Va bene, resto qui.","panic":"Va bene… va bene."}}],"truth":{"event_type":"{fight.event}","acceptable_event_types":["sicurezza.lite_violenza","sicurezza.aggressione"],"agencies_required":["{fight.agencies}"],"severity":{"optimal_s":240,"acceptable_s":600,"limit_s":1200},"critical_facts":["indirizzo","evento"],"hint_debrief":"Mai mandare il chiamante a verificare di persona: si mette in pericolo e si perde tempo. Un grido di dolore seguito dal silenzio richiede anche il 118."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
