INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('SIC_041', 'Truffa agli anziani', 'sicurezza', 1, 4, 100, 1, 'mattina,pomeriggio,sera,notte', 0, 0, '{"code":"SIC_041","title":"Truffa agli anziani","category":"sicurezza","phase":1,"difficulty":4,"weight":100,"min_rank":1,"time_bands":["mattina","pomeriggio","sera","notte"],"lang":"it","variables":{"location":{"pool":"stradario","zones":["centro","residenziale"],"floor":[0,4]},"sc":{"choice":[{"w":"(sottovoce) Ci sono due tecnici del gas in casa, vogliono che metta i gioielli nel frigorifero perché dicono che il gas li rovina…","wd":"Due falsi tecnici del gas in casa, in corso","s":"Sono ancora qui, in cucina.","sd":"I truffatori sono in casa ora","sev":{"optimal_s":180,"acceptable_s":420,"limit_s":900}},{"w":"Mi ha chiamato un carabiniere, dice che mio nipote ha fatto un incidente e che serve una cauzione. Sta arrivando un corriere a prendere i soldi.","wd":"Falsa telefonata per un incidente del nipote, corriere in arrivo per i soldi","s":"Il corriere dovrebbe arrivare tra dieci minuti.","sd":"Corriere atteso a minuti","sev":{"optimal_s":300,"acceptable_s":600,"limit_s":1200}},{"w":"Chiamo per mio padre: un''ora fa ha dato cinquemila euro a un finto avvocato che è venuto a casa.","wd":"Truffa già avvenuta un''ora fa, finto avvocato","s":"No, se n''è andato da un pezzo.","sd":"Truffatore già andato via","sev":{"optimal_s":900,"acceptable_s":1800,"limit_s":3600}}]}},"caller":{"gender":"f","phone_type":"any","panic_start":40,"ring_patience_s":35,"hold_patience_s":30,"reliability":0.9,"callback_chance":0.6},"opening":{"calm":"Buongiorno… scusi, forse è una sciocchezza, ma volevo chiedere una cosa.","panic":"Pronto… non so se sto facendo bene a chiamare…"},"facts":{"indirizzo":{"display":"{location.street} {location.number}, {location.zone_name}"},"evento":{"display":"{sc.wd}"},"stato":{"label":"Situazione attuale","display":"{sc.sd}"}},"nodes":[{"id":"q_dove","label":"Mi dica l''indirizzo: via e numero civico.","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":"{location.street} {location.number}.","panic":"{location.street}… il {location.number}!"},"error":{"threshold":65,"chance":0.4,"fact":"indirizzo","display":"{location.street} {location.number_wrong}, {location.zone_name}","reply":{"panic":"{location.street}… il {location.number_wrong}!"}}},{"id":"q_cosa","label":"Mi racconti cosa sta succedendo.","cost_s":8,"reveals":["evento"],"reply":{"calm":"{sc.w}","panic":"{sc.w}"}},{"id":"q_ora","label":"Le persone sono ancora lì, o devono arrivare?","cost_s":5,"reveals":["stato"],"reply":{"calm":"{sc.s}","panic":"{sc.s}"}},{"id":"a_avviso","type":"reassure","label":"Nessun tecnico, avvocato o carabiniere chiede soldi o gioielli a casa. Non consegni nulla e non apra: arrivano le forze dell''ordine.","cost_s":6,"panic_delta":-15,"reply":{"calm":"Oh Signore… va bene, non apro.","panic":"Va bene… va bene, non do niente."}}],"truth":{"event_type":"sicurezza.truffa","agencies_required":["{location.police}"],"severity":"{sc.sev}","critical_facts":["indirizzo","stato"],"hint_debrief":"Chi chiama per una truffa spesso esordisce scusandosi: va ascoltato. Se i truffatori sono in casa o in arrivo, è un intervento urgente."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('SIC_042', 'Ex compagno sotto casa', 'sicurezza', 1, 5, 100, 1, 'mattina,pomeriggio,sera,notte', 0, 0, '{"code":"SIC_042","title":"Ex compagno sotto casa","category":"sicurezza","phase":1,"difficulty":5,"weight":100,"min_rank":1,"time_bands":["mattina","pomeriggio","sera","notte"],"lang":"it","variables":{"location":{"pool":"stradario","zones":["centro","residenziale","colline"],"floor":[1,4]},"sc":{"choice":[{"w":"Il mio ex è sotto casa, suona in continuazione e urla. Ha un divieto di avvicinamento!","wd":"Ex compagno sotto casa nonostante un divieto di avvicinamento","d":"È giù in strada, vicino al portone.","dd":"In strada davanti al portone"},{"w":"Un uomo mi segue da tre giorni… adesso è qui davanti al portone e mi guarda.","wd":"Uomo che la segue da tre giorni, ora davanti al portone","d":"È fermo davanti al portone.","dd":"Davanti al portone"},{"w":"Il mio ex è salito sul pianerottolo e prende a calci la porta! Sto chiusa in bagno!","wd":"Ex compagno sul pianerottolo che prende a calci la porta","d":"È qui fuori! Sulla porta!","dd":"Sul pianerottolo, contro la porta di casa"}]}},"caller":{"gender":"f","phone_type":"mobile","panic_start":72,"ring_patience_s":35,"hold_patience_s":12,"reliability":0.95,"callback_chance":0.9},"opening":{"calm":"Pronto… c''è una persona che mi sta perseguitando, adesso è qui.","panic":"Pronto! È qui! È tornato, ho paura!"},"facts":{"indirizzo":{"display":"{location.street} {location.number}, {location.floor_text}"},"evento":{"display":"{sc.wd}"},"posizione":{"label":"Dove si trova lui","display":"{sc.dd}"},"pericoli":{"display":"Non sa se sia armato"}},"nodes":[{"id":"q_dove","label":"Mi dica l''indirizzo: via e numero civico.","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":"{location.street} {location.number}.","panic":"{location.street}… il {location.number}!"},"error":{"threshold":70,"chance":0.45,"fact":"indirizzo","display":"{location.street} {location.number_wrong}, {location.zone_name}","reply":{"panic":"{location.street}… il {location.number_wrong}!"}}},{"id":"q_cosa","label":"Cosa sta succedendo?","cost_s":6,"reveals":["evento"],"reply":{"calm":"{sc.w}","panic":"{sc.w}"}},{"id":"q_dove_lui","label":"Dove si trova lui esattamente?","cost_s":5,"reveals":["posizione"],"reply":{"calm":"{sc.d}","panic":"{sc.d}"}},{"id":"q_armi","label":"Sa se ha armi con sé?","cost_s":5,"reveals":["pericoli"],"reply":{"calm":"Non lo so… una volta mi ha fatto vedere un coltello.","panic":"Non lo so… una volta mi ha fatto vedere un coltello."}},{"id":"a_rassicura","type":"reassure","label":"Chiuda a chiave, non apra per nessun motivo e resti in una stanza lontana dalla porta. Resto in linea con lei.","cost_s":6,"panic_delta":-18,"reply":{"calm":"Va bene… grazie.","panic":"Sì… sì, va bene."}}],"truth":{"event_type":"sicurezza.molestie","acceptable_event_types":["sicurezza.violenza_domestica"],"agencies_required":["{location.police}"],"severity":{"optimal_s":180,"acceptable_s":420,"limit_s":900},"critical_facts":["indirizzo","posizione"],"hint_debrief":"Chi è perseguitato non va messo in attesa. Dove si trova l''aggressore e se è armato decidono come intervengono le forze dell''ordine."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('SIC_043', 'Rumori molesti', 'sicurezza', 1, 2, 100, 1, 'mattina,pomeriggio,sera,notte', 0, 0, '{"code":"SIC_043","title":"Rumori molesti","category":"sicurezza","phase":1,"difficulty":2,"weight":100,"min_rank":1,"time_bands":["mattina","pomeriggio","sera","notte"],"lang":"it","variables":{"location":{"pool":"stradario","zones":["centro","residenziale"],"floor":[1,4]},"sc":{"choice":[{"w":"C''è una festa nell''appartamento sopra, musica altissima alle due di notte, non si dorme.","wd":"Musica ad alto volume da una festa, notte fonda","event":"sicurezza.disturbo","ag":["{location.police}"],"sev":{"optimal_s":1800,"acceptable_s":3600,"limit_s":7200}},{"w":"Sopra di me sento urlare e rompere cose da mezz''ora, poi una donna che piange.","wd":"Urla, oggetti rotti e una donna che piange dall''appartamento sopra","event":"sicurezza.violenza_domestica","ag":["{location.police}"],"sev":{"optimal_s":240,"acceptable_s":600,"limit_s":1200}},{"w":"Il cane del vicino abbaia da sei ore, i padroni sono via.","wd":"Cane che abbaia da ore, proprietari assenti","event":"sicurezza.disturbo","ag":["{location.police}"],"sev":{"optimal_s":3600,"acceptable_s":7200,"limit_s":14400}}],"weights":[45,25,30]}},"caller":{"gender":"any","phone_type":"any","panic_start":15,"ring_patience_s":35,"hold_patience_s":30,"reliability":1,"callback_chance":0.7},"opening":{"calm":"Buonasera, scusate l''ora, chiamo per dei rumori dall''appartamento vicino.","panic":"Pronto, c''è un rumore terribile qui sopra!"},"facts":{"indirizzo":{"display":"{location.street} {location.number}, appartamento vicino a quello del chiamante"},"rumori":{"label":"Cosa si sente","display":"{sc.wd}"}},"nodes":[{"id":"q_dove","label":"Mi dica l''indirizzo: via e numero civico.","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":"{location.street} {location.number}.","panic":"{location.street}… il {location.number}!"}},{"id":"q_cosa","label":"Che rumori sente esattamente?","cost_s":6,"reveals":["rumori"],"reply":{"calm":"{sc.w}","panic":"{sc.w}"}}],"truth":{"event_type":"{sc.event}","acceptable_event_types":["sicurezza.lite_violenza","sicurezza.disturbo"],"agencies_required":"{sc.ag}","severity":"{sc.sev}","critical_facts":["rumori"],"hint_debrief":"Una chiamata per «rumori» va sempre fatta descrivere: una festa e una lite violenta iniziano con la stessa frase."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('SIC_044', 'Pericolo sulla strada', 'sicurezza', 1, 3, 100, 1, 'mattina,pomeriggio,sera,notte', 0, 0, '{"code":"SIC_044","title":"Pericolo sulla strada","category":"sicurezza","phase":1,"difficulty":3,"weight":100,"min_rank":1,"time_bands":["mattina","pomeriggio","sera","notte"],"lang":"it","variables":{"location":{"pool":"stradario","zones":["colline","industriale","residenziale"],"floor":[0,0]},"sc":{"choice":[{"w":"Davanti a me c''è un''auto che zigzaga, finisce sull''altra corsia, secondo me è ubriaco.","wd":"Auto che zigzaga invadendo l''altra corsia","v":"Una Panda rossa, la targa inizia con EF.","vd":"Panda rossa, targa che inizia con EF","event":"sicurezza.pericolo_viabilita","ag":["{location.police}"]},{"w":"C''è una macchina contromano sul viale! Sta andando dritta verso le altre!","wd":"Auto contromano","v":"Una station wagon grigia, non vedo la targa.","vd":"Station wagon grigia","event":"sicurezza.pericolo_viabilita","ag":["{location.police}"]},{"w":"Un camion ha perso il carico, ci sono dei tubi di ferro in mezzo alla carreggiata!","wd":"Tubi di ferro in carreggiata persi da un camion","v":"Il camion non si è fermato, era bianco.","vd":"Camion bianco, non si è fermato","event":"sicurezza.pericolo_viabilita","ag":["{location.police}","115"]}]}},"caller":{"gender":"m","phone_type":"mobile","panic_start":45,"ring_patience_s":35,"hold_patience_s":30,"reliability":0.95,"callback_chance":0.3},"opening":{"calm":"Buonasera, sto guidando e c''è una situazione pericolosa sulla strada.","panic":"Pronto! C''è un pericolo sulla strada, qualcuno si farà male!"},"facts":{"indirizzo":{"display":"{location.street}, direzione {location.landmark}"},"pericolo":{"label":"Pericolo","display":"{sc.wd}"},"veicoli":{"display":"{sc.vd}"}},"nodes":[{"id":"q_dove","label":"Su che strada si trova e in che direzione sta andando?","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":"Sono in {location.street}, verso {location.landmark}.","panic":"{location.street}! Verso {location.landmark}!"},"error":{"threshold":65,"chance":0.4,"fact":"indirizzo","display":"{location.street_wrong} (incerto)","reply":{"panic":"In {location.street_wrong}… credo, non ne sono sicuro!"}}},{"id":"q_cosa","label":"Cosa vede esattamente?","cost_s":6,"reveals":["pericolo"],"reply":{"calm":"{sc.w}","panic":"{sc.w}"}},{"id":"q_veicolo","label":"Riesce a descrivermi il veicolo? Colore, modello, targa?","cost_s":6,"reveals":["veicoli"],"reply":{"calm":"{sc.v}","panic":"{sc.v}"}},{"id":"a_accosta","type":"reassure","label":"Se sta guidando si fermi in un punto sicuro prima di continuare a parlare, e non provi a inseguirlo.","cost_s":6,"panic_delta":-10,"reply":{"calm":"Ok, accosto.","panic":"Va bene, mi fermo!"}}],"truth":{"event_type":"{sc.event}","acceptable_event_types":["incendio_tecnico.danni_maltempo"],"agencies_required":"{sc.ag}","agencies_acceptable":["115"],"severity":{"optimal_s":180,"acceptable_s":420,"limit_s":900},"critical_facts":["indirizzo","veicoli"],"hint_debrief":"Per un pericolo in movimento servono strada, direzione e descrizione del veicolo: le pattuglie devono sapere dove intercettarlo."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('SIC_045', 'Aggressione all''autista', 'sicurezza', 1, 4, 100, 1, 'mattina,pomeriggio,sera,notte', 0, 0, '{"code":"SIC_045","title":"Aggressione all''autista","category":"sicurezza","phase":1,"difficulty":4,"weight":100,"min_rank":1,"time_bands":["mattina","pomeriggio","sera","notte"],"lang":"it","variables":{"location":{"pool":"stradario","zones":["centro","residenziale","industriale"],"floor":[0,0]},"sc":{"choice":[{"w":"Un passeggero ha preso a pugni l''autista del bus! Adesso è sceso e sta andando via a piedi.","wd":"Autista del bus aggredito, l''aggressore si allontana a piedi","f":"L''autista perde sangue dal naso, dice che non ci vede bene da un occhio.","fd":"Autista ferito al volto","ag":["{location.police}","118"]},{"w":"Alla fermata un uomo sta molestando una ragazza, la tocca, lei piange… è ancora qui.","wd":"Uomo che molesta una ragazza alla fermata, ancora presente","f":"Lei non è ferita, ma è sconvolta.","fd":"Nessun ferito, vittima sconvolta","ag":["{location.police}"]},{"w":"Un tizio ha minacciato il controllore con un coltello ed è sceso alla fermata.","wd":"Controllore minacciato con un coltello, l''uomo è sceso","f":"No, nessuno è ferito.","fd":"Nessun ferito","ag":["{location.police}"]}]}},"caller":{"gender":"any","phone_type":"mobile","panic_start":60,"ring_patience_s":35,"hold_patience_s":30,"reliability":0.95,"callback_chance":0.6},"opening":{"calm":"Pronto, sull''autobus c''è stata un''aggressione.","panic":"Pronto! Un''aggressione sull''autobus, presto!"},"facts":{"indirizzo":{"display":"{location.street}, vicino a {location.landmark} ({location.zone_name})"},"evento":{"display":"{sc.wd}"},"feriti":{"display":"{sc.fd}"},"descrizione":{"label":"Descrizione","display":"Uomo sui quarant''anni, giubbotto verde, barba"}},"nodes":[{"id":"q_dove","label":"Dove si trova l''autobus? Via o fermata.","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":"Alla fermata di {location.street}, vicino a {location.landmark}.","panic":"{location.street}!"},"error":{"threshold":65,"chance":0.4,"fact":"indirizzo","display":"{location.street_wrong} (incerto)","reply":{"panic":"In {location.street_wrong}… credo, non ne sono sicuro!"}}},{"id":"q_cosa","label":"Cosa è successo?","cost_s":6,"reveals":["evento"],"reply":{"calm":"{sc.w}","panic":"{sc.w}"}},{"id":"q_feriti","label":"Ci sono feriti?","cost_s":4,"reveals":["feriti"],"reply":{"calm":"{sc.f}","panic":"{sc.f}"}},{"id":"q_descr","label":"Com''è fatto l''aggressore e dove è andato?","cost_s":6,"reveals":["descrizione"],"reply":{"calm":"Sui quarant''anni, giubbotto verde, barba. È andato verso {location.landmark}.","panic":"Sui quarant''anni, giubbotto verde, barba. È andato verso {location.landmark}."}},{"id":"a_rassicura","type":"reassure","label":"Restate sull''autobus con le porte chiuse e non inseguitelo.","cost_s":6,"panic_delta":-12,"reply":{"calm":"Va bene… grazie.","panic":"Sì… sì, va bene."}}],"truth":{"event_type":"sicurezza.aggressione","acceptable_event_types":["sicurezza.molestie","sicurezza.lite_violenza"],"agencies_required":"{sc.ag}","agencies_acceptable":["118"],"severity":{"optimal_s":120,"acceptable_s":300,"limit_s":900},"critical_facts":["indirizzo","descrizione"],"hint_debrief":"Chiedere se ci sono feriti decide il 118; la descrizione dell''aggressore aiuta a fermarlo mentre è ancora vicino."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('SIC_053', 'Stanno rubando un''auto', 'sicurezza', 1, 3, 100, 1, 'mattina,pomeriggio,sera,notte', 0, 0, '{"code":"SIC_053","title":"Stanno rubando un''auto","category":"sicurezza","phase":1,"difficulty":3,"weight":100,"min_rank":1,"time_bands":["mattina","pomeriggio","sera","notte"],"lang":"it","variables":{"location":{"pool":"stradario","zones":["residenziale","centro","industriale"],"floor":[0,0]},"sc":{"choice":[{"w":"Due ragazzi hanno rotto il finestrino di una macchina e stanno smontando la radio.","wd":"Due giovani che rubano l''autoradio da un''auto con finestrino rotto","s":"Sono ancora lì.","sd":"Ancora sul posto"},{"w":"Hanno appena rubato la mia macchina! L''ho vista partire dal parcheggio!","wd":"Furto d''auto appena avvenuto","s":"È andata verso {location.landmark}, una Golf grigia, targa FG 214.","sd":"Golf grigia targa FG 214 verso {location.landmark}"}]}},"caller":{"gender":"any","phone_type":"any","panic_start":45,"ring_patience_s":35,"hold_patience_s":30,"reliability":0.95,"callback_chance":0.6},"opening":{"calm":"Pronto, stanno rubando una macchina qui sotto.","panic":"Pronto! Mi hanno rubato la macchina!"},"facts":{"indirizzo":{"display":"{location.street}, vicino a {location.landmark} ({location.zone_name})"},"evento":{"display":"{sc.wd}"},"fuga":{"label":"Dove sono ora","display":"{sc.sd}"}},"nodes":[{"id":"q_dove","label":"Dove si trova?","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":"In {location.street}, davanti a {location.landmark}.","panic":"{location.street}!"}},{"id":"q_cosa","label":"Cosa sta succedendo?","cost_s":6,"reveals":["evento"],"reply":{"calm":"{sc.w}","panic":"{sc.w}"}},{"id":"q_ora","label":"Sono ancora lì? Da che parte sono andati?","cost_s":5,"reveals":["fuga"],"reply":{"calm":"{sc.s}","panic":"{sc.s}"}},{"id":"a_rassicura","type":"reassure","label":"Non intervenga: continui a osservare da dove si trova, se è al sicuro.","cost_s":6,"panic_delta":-10,"reply":{"calm":"Va bene… grazie.","panic":"Sì… sì, va bene."}}],"truth":{"event_type":"sicurezza.furto_in_corso","agencies_required":["{location.police}"],"severity":{"optimal_s":180,"acceptable_s":420,"limit_s":900},"critical_facts":["indirizzo","fuga"],"hint_debrief":"Per un furto appena avvenuto contano direzione di fuga e descrizione del veicolo: le pattuglie possono ancora intercettarlo."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('STR_005', 'Tamponamento stradale', 'sicurezza', 1, 2, 100, 1, 'mattina,pomeriggio,sera,notte', 1, 0, '{"code":"STR_005","title":"Tamponamento stradale","category":"sicurezza","phase":1,"difficulty":2,"weight":100,"min_rank":1,"time_bands":["mattina","pomeriggio","sera","notte"],"can_duplicate":true,"lang":"it","variables":{"location":{"pool":"stradario","zones":["residenziale","industriale","colline"],"floor":[0,0]},"injury":{"choice":[{"text":"No, siamo tutti fuori dalle macchine, solo tanto spavento.","display":"Nessun ferito, tutti fuori dai veicoli","agencies":[],"event":"sicurezza.incidente_stradale"},{"text":"La signora dell''altra macchina dice che le fa male il collo, è ancora seduta dentro.","display":"Una donna con dolore al collo, ancora nel veicolo","agencies":["118"],"event":"sanitaria.trauma_stradale"}],"weights":[55,45]},"veh":{"choice":[{"text":"Due macchine. Niente fumo, solo il paraurti distrutto.","display":"Due auto, nessun fumo o perdita","agencies":[]},{"text":"Due macchine… e dalla mia esce del liquido sotto il motore, sento odore di benzina.","display":"Due auto, perdita di liquido e odore di benzina","agencies":["115"]}],"weights":[75,25]},"road":{"choice":[{"text":"Siamo a bordo strada, le macchine passano piano.","display":"Veicoli a bordo strada, traffico lento"},{"text":"Siamo in mezzo alla carreggiata, la gente frena all''ultimo!","display":"Veicoli in mezzo alla carreggiata, rischio di altri urti"}]}},"caller":{"gender":"m","phone_type":"mobile","panic_start":40,"ring_patience_s":35,"hold_patience_s":30,"reliability":0.95,"callback_chance":0.8},"opening":{"calm":"Pronto, buonasera. Ho appena avuto un incidente, un tamponamento.","panic":"Pronto?! C''è stato un incidente, mi hanno tamponato, qui è un casino!"},"facts":{"indirizzo":{"display":"{location.street}, vicino a {location.landmark} ({location.zone_name})"},"feriti":{"display":"{injury.display}"},"veicoli":{"display":"{veh.display}"},"pericoli":{"display":"{road.display}"}},"nodes":[{"id":"q_dove","label":"In che strada si trova? C''è un incrocio o un punto di riferimento?","cost_s":7,"reveals":["indirizzo"],"reply":{"calm":"In {location.street}, poco dopo {location.landmark}.","panic":"In {location.street}… vicino a {location.landmark}, credo!"},"error":{"threshold":65,"chance":0.35,"fact":"indirizzo","display":"{location.street_wrong} (incerto)","reply":{"panic":"In {location.street_wrong}… o forse no, non lo so, non sono di qui!"}}},{"id":"q_feriti","label":"Ci sono feriti? Qualcuno è rimasto dentro un''auto?","cost_s":6,"reveals":["feriti"],"reply":{"calm":"{injury.text}","panic":"{injury.text}"}},{"id":"q_veicoli","label":"Quanti veicoli sono coinvolti? Esce fumo o perdono liquidi?","cost_s":6,"reveals":["veicoli"],"reply":{"calm":"{veh.text}","panic":"{veh.text}"}},{"id":"q_strada","label":"Le auto bloccano la strada? È pericoloso per chi passa?","cost_s":5,"reveals":["pericoli"],"reply":{"calm":"{road.text}","panic":"{road.text}"}},{"id":"a_sicurezza","type":"reassure","label":"Accendete le quattro frecce e mettetevi al sicuro oltre il guardrail o sul marciapiede.","cost_s":6,"panic_delta":-15,"reply":{"calm":"Sì, va bene, lo dico anche agli altri.","panic":"Ok… ok, ci spostiamo."}}],"truth":{"event_type":"{injury.event}","agencies_required":["{location.police}","{injury.agencies}","{veh.agencies}"],"severity":{"optimal_s":300,"acceptable_s":900,"limit_s":1800},"critical_facts":["indirizzo","feriti","veicoli"],"hint_debrief":"In un incidente la competenza tra Polizia e Carabinieri dipende dalla zona; feriti e perdite di carburante aggiungono 118 e Vigili del fuoco."},"duplicates":{"chance":0.35,"max":1,"delay_s":[30,180],"near_twin_chance":0.1},"witness_opening":{"calm":"Buonasera, in {location.street} c''è stato un tamponamento, ci sono due auto ferme.","panic":"Pronto, un incidente in {location.street}, due macchine!"}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('STR_013', 'Auto fuori strada, conducente incastrato', 'sanitaria', 1, 6, 75, 2, 'mattina,pomeriggio,sera,notte', 1, 0, '{"code":"STR_013","title":"Auto fuori strada, conducente incastrato","category":"sanitaria","phase":1,"difficulty":6,"weight":75,"min_rank":2,"time_bands":["mattina","pomeriggio","sera","notte"],"can_duplicate":true,"lang":"it","duplicates":{"chance":0.7,"max":3,"delay_s":[20,160],"near_twin_chance":0},"variables":{"location":{"pool":"stradario","zones":["colline","industriale"],"floor":[0,0]},"veh":{"choice":[{"text":"C''è un odore fortissimo di benzina, sotto la macchina c''è una pozza!","display":"Forte odore di benzina, pozza sotto l''auto"},{"text":"Esce del fumo dal cofano, sempre di più!","display":"Fumo dal cofano in aumento"}]}},"caller":{"gender":"m","phone_type":"mobile","panic_start":72,"ring_patience_s":30,"hold_patience_s":20,"reliability":0.95,"callback_chance":0.9},"opening":{"calm":"Pronto, un''auto è finita fuori strada contro un albero, c''è uno dentro che non riesce a uscire!","panic":"Pronto! Incidente! Una macchina contro un albero, c''è uno incastrato dentro!"},"witness_opening":{"calm":"Buonasera, sto passando in {location.street}: c''è un''auto finita contro un albero, si stanno fermando altre persone.","panic":"Pronto, in {location.street} c''è una macchina schiantata contro un albero!"},"facts":{"indirizzo":{"display":"{location.street}, vicino a {location.landmark} ({location.zone_name})"},"feriti":{"display":"Conducente incastrato, sanguina dalla testa, risponde a fatica"},"veicoli":{"display":"{veh.display}"},"pericoli":{"display":"Auto ferma di traverso sulla carreggiata"}},"nodes":[{"id":"q_dove","label":"Dove siete esattamente? Via e punto di riferimento.","cost_s":7,"reveals":["indirizzo"],"reply":{"calm":"In {location.street}, poco dopo {location.landmark}.","panic":"{location.street}! Dopo {location.landmark}!"},"error":{"threshold":70,"chance":0.4,"fact":"indirizzo","display":"{location.street_wrong} (incerto)","reply":{"panic":"In {location.street_wrong}… credo… non lo so!"}}},{"id":"q_feriti","label":"Quante persone sono ferite? Chi è bloccato come sta?","cost_s":7,"reveals":["feriti"],"reply":{"calm":"Solo il conducente. È incastrato, perde sangue dalla testa, risponde a fatica.","panic":"Uno! Incastrato, sangue dalla testa, parla appena!"}},{"id":"q_fuoco","label":"Esce fumo o perde carburante?","cost_s":5,"reveals":["veicoli"],"reply":{"calm":"{veh.text}","panic":"{veh.text}"}},{"id":"q_strada","label":"L''auto blocca la strada? Altri rischi per chi passa?","cost_s":5,"reveals":["pericoli"],"reply":{"calm":"È di traverso, le macchine devono rallentare.","panic":"È in mezzo alla strada!"}},{"id":"a_sicurezza","type":"reassure","label":"Non spostate il ferito, niente sigarette, mettetevi al sicuro fuori dalla strada.","cost_s":6,"panic_delta":-15,"reply":{"calm":"D''accordo, lo dico agli altri.","panic":"Sì… sì, va bene."}}],"truth":{"event_type":"sanitaria.trauma_stradale","agencies_required":["118","115","{location.police}"],"severity":{"optimal_s":300,"acceptable_s":600,"limit_s":1200},"critical_facts":["indirizzo","feriti"],"hint_debrief":"Una persona incastrata richiede i Vigili del fuoco per l''estricazione, oltre a 118 e forze dell''ordine. I testimoni che chiamano dopo vanno accorpati all''evento."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('STR_049', 'Pedone investito', 'sanitaria', 1, 4, 100, 1, 'mattina,pomeriggio,sera,notte', 1, 0, '{"code":"STR_049","title":"Pedone investito","category":"sanitaria","phase":1,"difficulty":4,"weight":100,"min_rank":1,"time_bands":["mattina","pomeriggio","sera","notte"],"lang":"it","can_duplicate":true,"duplicates":{"chance":0.45,"max":2,"delay_s":[20,120],"near_twin_chance":0.1},"witness_opening":{"calm":"Buonasera, in {location.street} hanno investito qualcuno, vicino a {location.landmark}.","panic":"Pronto! Un investimento in {location.street}!"},"variables":{"location":{"pool":"stradario","zones":["centro","residenziale"],"floor":[0,0]},"sc":{"choice":[{"w":"Una signora anziana è stata investita sulle strisce! La macchina si è fermata, il conducente è sotto shock.","wd":"Anziana investita sulle strisce, conducente fermo sul posto","f":"È a terra, cosciente, si lamenta per la gamba e ha un taglio in testa.","fd":"Cosciente, ferita alla testa e alla gamba","v":"Il conducente è qui, sta seduto sul marciapiede.","vd":"Conducente sul posto"},{"w":"Hanno investito un uomo e sono scappati! Una macchina scura!","wd":"Pedone investito, auto pirata fuggita","f":"Non si muove, respira ma non risponde!","fd":"Non risponde, respira","v":"Una berlina scura, la targa finiva con 7 L, è andata verso {location.landmark}.","vd":"Berlina scura, targa finale «7L», fuggita verso {location.landmark}"},{"w":"Un ciclista è stato urtato da un''auto che girava, è caduto.","wd":"Ciclista urtato da un''auto in svolta","f":"Si è rialzato, sanguina dal gomito e zoppica.","fd":"Si è rialzato, ferita al gomito, zoppica","v":"L''automobilista si è fermato.","vd":"Automobilista sul posto"}]}},"caller":{"gender":"any","phone_type":"mobile","panic_start":65,"ring_patience_s":35,"hold_patience_s":30,"reliability":0.95,"callback_chance":0.6},"opening":{"calm":"Pronto, hanno investito una persona!","panic":"Pronto! Hanno investito qualcuno, presto!"},"facts":{"indirizzo":{"display":"{location.street}, vicino a {location.landmark} ({location.zone_name})"},"evento":{"display":"{sc.wd}"},"feriti":{"display":"{sc.fd}"},"veicoli":{"display":"{sc.vd}"}},"nodes":[{"id":"q_dove","label":"Dove è successo? Via e punto di riferimento.","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":"In {location.street}, vicino a {location.landmark}.","panic":"{location.street}! Vicino a {location.landmark}!"},"error":{"threshold":65,"chance":0.4,"fact":"indirizzo","display":"{location.street_wrong} (incerto)","reply":{"panic":"In {location.street_wrong}… credo, non ne sono sicuro!"}}},{"id":"q_cosa","label":"Cosa è successo?","cost_s":5,"reveals":["evento"],"reply":{"calm":"{sc.w}","panic":"{sc.w}"}},{"id":"q_feriti","label":"Come sta la persona investita? Risponde?","cost_s":6,"reveals":["feriti"],"reply":{"calm":"{sc.f}","panic":"{sc.f}"}},{"id":"q_veicolo","label":"Il veicolo è ancora lì? Com''era?","cost_s":5,"reveals":["veicoli"],"reply":{"calm":"{sc.v}","panic":"{sc.v}"}},{"id":"a_rassicura","type":"reassure","label":"Non spostate la persona, copritela e deviate il traffico con l''aiuto di altri, restando al sicuro.","cost_s":6,"panic_delta":-12,"reply":{"calm":"Va bene… grazie.","panic":"Sì… sì, va bene."}}],"truth":{"event_type":"sanitaria.trauma_stradale","acceptable_event_types":["sicurezza.incidente_stradale"],"agencies_required":["118","{location.police}"],"severity":{"optimal_s":240,"acceptable_s":480,"limit_s":1200},"critical_facts":["indirizzo","feriti"],"hint_debrief":"In un investimento servono sempre 118 e forze dell''ordine. Se il conducente è fuggito, la descrizione dell''auto va presa subito."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('STR_050', 'Motociclista a terra', 'sanitaria', 1, 4, 100, 1, 'mattina,pomeriggio,sera,notte', 1, 0, '{"code":"STR_050","title":"Motociclista a terra","category":"sanitaria","phase":1,"difficulty":4,"weight":100,"min_rank":1,"time_bands":["mattina","pomeriggio","sera","notte"],"lang":"it","can_duplicate":true,"duplicates":{"chance":0.3,"max":1,"delay_s":[30,150],"near_twin_chance":0},"witness_opening":{"calm":"Buonasera, in {location.street} c''è un motociclista caduto.","panic":"Pronto, un incidente con una moto in {location.street}!"},"variables":{"location":{"pool":"stradario","zones":["colline","industriale"],"floor":[0,0]},"sc":{"choice":[{"w":"Una moto è scivolata in curva, il motociclista è a terra e non si muove.","wd":"Moto scivolata in curva, motociclista immobile","f":"Ha il casco, respira ma non risponde.","fd":"Casco indossato, respira, non risponde","c":"No, niente fumo.","cd":"Nessun fumo o perdita","ag":["118","{location.police}"]},{"w":"È caduto un motociclista, è seduto per terra.","wd":"Motociclista caduto, seduto a terra","f":"Risponde, ma ha la gamba storta e urla dal dolore.","fd":"Cosciente, gamba deformata","c":"No.","cd":"Nessun fumo o perdita","ag":["118","{location.police}"]},{"w":"Una moto si è scontrata con un''auto, il motociclista è volato nel fosso!","wd":"Scontro moto-auto, motociclista nel fosso","f":"È nel fosso, si lamenta, non riesce ad alzarsi.","fd":"Nel fosso, cosciente, non si alza","c":"La moto perde benzina sull''asfalto, c''è una pozza.","cd":"Perdita di benzina dalla moto","ag":["118","115","{location.police}"]}]}},"caller":{"gender":"any","phone_type":"mobile","panic_start":60,"ring_patience_s":35,"hold_patience_s":30,"reliability":0.95,"callback_chance":0.6},"opening":{"calm":"Pronto, c''è stato un incidente con una moto.","panic":"Pronto! Un motociclista è caduto, presto!"},"facts":{"indirizzo":{"display":"{location.street}, vicino a {location.landmark} ({location.zone_name})"},"evento":{"display":"{sc.wd}"},"feriti":{"display":"{sc.fd}"},"veicoli":{"display":"{sc.cd}"}},"nodes":[{"id":"q_dove","label":"Dove siete? Strada e punto di riferimento.","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":"In {location.street}, poco dopo {location.landmark}.","panic":"{location.street}! Dopo {location.landmark}!"},"error":{"threshold":65,"chance":0.4,"fact":"indirizzo","display":"{location.street_wrong} (incerto)","reply":{"panic":"In {location.street_wrong}… credo, non ne sono sicuro!"}}},{"id":"q_cosa","label":"Cosa è successo?","cost_s":5,"reveals":["evento"],"reply":{"calm":"{sc.w}","panic":"{sc.w}"}},{"id":"q_feriti","label":"Come sta il motociclista? Risponde?","cost_s":6,"reveals":["feriti"],"reply":{"calm":"{sc.f}","panic":"{sc.f}"}},{"id":"q_perdite","label":"La moto perde carburante o fuma?","cost_s":5,"reveals":["veicoli"],"reply":{"calm":"{sc.c}","panic":"{sc.c}"}},{"id":"a_casco","type":"reassure","label":"Non togliete il casco e non muovetelo: coprite il ferito e segnalate l''incidente a chi arriva.","cost_s":6,"panic_delta":-12,"reply":{"calm":"Va bene, il casco non lo tocchiamo.","panic":"Ok! Non lo tocchiamo!"}}],"truth":{"event_type":"sanitaria.trauma_stradale","agencies_required":"{sc.ag}","severity":{"optimal_s":240,"acceptable_s":480,"limit_s":1200},"critical_facts":["indirizzo","feriti"],"hint_debrief":"Con un motociclista a terra il casco non va tolto: può peggiorare una lesione alla colonna. Una perdita di carburante aggiunge i Vigili del fuoco."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
